-- ===== 0104z_park_old_inbox.sql =====
/*
 * Park the abandoned 0062 inbox table so 0105 can create its own.
 *
 * An earlier inbox design (0062_berichten.sql, 2 Oct 2026, on another branch)
 * was applied to the database and left a table public.inbox_messages keyed on
 * conversation_id. 0105 needs that name for a different table keyed on
 * thread_id, and "create table if not exists" silently kept the old one, so
 * 0105 failed with: column "thread_id" does not exist. No code on main or
 * studio-shell reads the old table (checked 21 Nov 2026).
 *
 * Renamed, not dropped: whatever it holds stays, under inbox_messages_0062.
 * Its indexes are renamed too, because inbox_messages_pkey and friends are
 * schema-wide names the new table needs. inbox_conversations does not clash
 * and is left alone.
 *
 * Only acts on the old shape (a conversation_id column), so it is a no-op on
 * a database that never had 0062. Run before 0105. Idempotent.
 */
do $$
declare
  r record;
begin
  if exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'inbox_messages' and column_name = 'conversation_id'
  ) then
    alter table public.inbox_messages rename to inbox_messages_0062;
    for r in select indexname from pg_indexes where schemaname = 'public' and tablename = 'inbox_messages_0062' loop
      execute format('alter index public.%I rename to %I', r.indexname, left(r.indexname, 58) || '_0062');
    end loop;
  end if;
end $$;

select to_regclass('public.inbox_messages_0062') is not null as old_table_parked;

-- ===== 0106_whatsapp_quotes.sql =====
/*
 * Price questions found in the owner's WhatsApp history, one row per question.
 *
 * Filled by a local import: the chats themselves stay on the owner's Mac; only
 * these extracted fields and a short excerpt come here. Every row points back
 * to the exact chat and messages it came from, so a number in the price list
 * can always be checked against what was really said.
 *
 * Separate from leads.quoted_price (0029): that is the one indicative price the
 * website form showed; this is every price ever named in a chat.
 *
 * First shipped as 0076_whatsapp_quotes.sql on the old main; renumbered here.
 * Run after 0105. Idempotent: safe on a database that already ran 0076.
 */

create table if not exists public.whatsapp_quotes (
  id uuid primary key default gen_random_uuid(),

  /*
   * Where it was said. WhatsApp has no link to a single message, so the
   * "link" is the chat, the message ids and the time: enough to find it in
   * the export on the Mac, or by scrolling on the phone.
   * source_key = chat_jid || ':' || ask_message_id, so re-running the import
   * updates a row instead of duplicating it.
   */
  source_key          text not null unique,
  chat_jid            text not null,
  phone               text,
  contact_name        text,
  ask_message_id      text not null,
  quote_message_id    text,
  context_message_ids text[] not null default '{}',
  asked_at            timestamptz,
  quoted_at           timestamptz,
  /* Only the few messages around the price, as [{id, at, from_me, text}]. Never the whole chat. */
  context             jsonb not null default '[]',

  make      text not null,
  model     text,
  year      integer check (year is null or year between 1970 and 2100),
  kenteken  text,

  /* Null = the chat doesn't make it clear. */
  scenario  public.job_scenario,
  problem   text not null,
  product   text,
  keyless   boolean,

  city            text,
  postcode        text,
  urgency         text not null default 'onbekend'
    check (urgency in ('nu', 'vandaag', 'deze_week', 'later', 'onbekend')),
  requested_time  text,
  conditions      text,

  /* The price exactly as said. */
  price_amount  numeric(10,2) check (price_amount is null or price_amount >= 0),
  price_max     numeric(10,2) check (price_max is null or price_max >= 0),
  price_kind    text not null default 'geen'
    check (price_kind in ('vast', 'vanaf', 'bandbreedte', 'geen')),
  price_vat     text not null default 'onbekend'
    check (price_vat in ('incl', 'excl', 'onbekend')),
  /* True when the chat named no BTW basis and 'incl' was filled in by the
     owner's rule (21 Nov 2026: bare prices are incl. BTW), not read from the chat. */
  price_vat_assumed boolean not null default false,
  /*
   * Including 21% BTW, computed here and never by the model. Null when the
   * chat doesn't say incl or excl: guessing the basis would put a 21% error
   * into the price list.
   */
  price_incl numeric(10,2) generated always as (
    case price_vat
      when 'incl' then price_amount
      when 'excl' then round(price_amount * 1.21, 2)
    end
  ) stored,
  quote_excerpt text,

  /*
   * Who ended it and why. lost_* is the customer saying no; declined_* is us
   * saying no. Kept apart because the fixes are opposite: a price loss is a
   * pricing decision, a decline is a tool, part or technician we don't have.
   */
  outcome      text not null default 'onbekend'
    check (outcome in ('gewonnen', 'verloren', 'geen_reactie', 'afgewezen_door_ons', 'onbekend')),
  lost_reason  text
    check (lost_reason is null or lost_reason in
      ('prijs', 'tijd', 'klant_elders', 'dealer', 'zelf_opgelost', 'vertrouwen', 'anders', 'onbekend')),
  lost_detail  text,
  declined_reason text
    check (declined_reason is null or declined_reason in
      ('auto_niet_mogelijk', 'geen_onderdeel', 'geen_monteur', 'te_ver', 'te_laat_op_dag', 'niet_rendabel', 'anders')),
  declined_detail text,

  /* Negotiation. Same VAT basis as price_vat. */
  price_objection     boolean not null default false,
  time_objection      boolean not null default false,
  competitor_price    numeric(10,2),
  competitor          text,
  customer_budget     numeric(10,2),
  we_lowered_price    boolean not null default false,
  final_price_amount  numeric(10,2),
  we_followed_up      boolean not null default false,
  source              text not null default 'onbekend'
    check (source in ('google', 'advertentie', 'website', 'marktplaats', 'doorverwezen', 'terugkerende_klant', 'garage_b2b', 'onbekend')),

  /*
   * Speed, from message timestamps by the import script, never by the model.
   * In emergency work the first answer often decides the job.
   */
  first_reply_at  timestamptz,
  reply_minutes   integer generated always as (
    case when first_reply_at is not null and asked_at is not null
      then greatest(0, (extract(epoch from (first_reply_at - asked_at)) / 60)::integer)
    end
  ) stored,

  /*
   * "Gewonnen" from the chat is a claim; a job in the CRM for the same phone
   * within 14 days is proof. Set by the import, null when no job matches
   * (most history predates the CRM).
   */
  job_id  uuid references public.jobs (id) on delete set null,

  /* The model's own certainty, and the owner's check of it. */
  confidence    numeric(3,2) check (confidence is null or confidence between 0 and 1),
  review        text not null default 'nieuw'
    check (review in ('nieuw', 'goedgekeurd', 'afgewezen')),
  extracted_by  text,
  extracted_at  timestamptz not null default now(),
  created_at    timestamptz not null default now()
);

create index if not exists whatsapp_quotes_car_idx
  on public.whatsapp_quotes (lower(make), lower(coalesce(model, '')), scenario);
create index if not exists whatsapp_quotes_phone_idx
  on public.whatsapp_quotes (phone) where phone is not null;
create index if not exists whatsapp_quotes_outcome_idx
  on public.whatsapp_quotes (outcome, lost_reason);

comment on table public.whatsapp_quotes is
  'Price questions extracted from the owner''s WhatsApp history. One row per question, each pointing back to its chat and messages.';

alter table public.whatsapp_quotes enable row level security;

/* Office only, like agent_conversations: these are customers' own words. No
   insert/update policy: the import writes with the service-role key. */
drop policy if exists whatsapp_quotes_read on public.whatsapp_quotes;
create policy whatsapp_quotes_read on public.whatsapp_quotes
  for select
  using (public.crm_role() in ('owner', 'kantoor'));

/*
 * The office checks each extracted row on /admin/whatsapp-analyse and marks it
 * goedgekeurd or afgewezen. Who and when, so a mark can be traced. The API
 * route only ever writes these three columns.
 */
alter table public.whatsapp_quotes add column if not exists reviewed_at timestamptz;
alter table public.whatsapp_quotes add column if not exists reviewed_by uuid references auth.users (id) on delete set null;

drop policy if exists whatsapp_quotes_review on public.whatsapp_quotes;
create policy whatsapp_quotes_review on public.whatsapp_quotes
  for update
  using (public.crm_role() in ('owner', 'kantoor'))
  with check (public.crm_role() in ('owner', 'kantoor'));

/*
 * The price list: what we actually asked, per car, 5-year band and job, and
 * how often it won. Only rows with a known incl-BTW price that the owner
 * hasn't rejected. quote_ids opens every line back to the chats behind it.
 * security_invoker, so the view obeys the table's office-only policy.
 */
create or replace view public.whatsapp_price_list
with (security_invoker = true) as
select
  make,
  model,
  (year / 5) * 5                                            as year_from,
  (year / 5) * 5 + 4                                        as year_to,
  scenario,
  count(*)                                                  as quotes,
  min(price_incl)                                           as min_incl,
  percentile_cont(0.5) within group (order by price_incl)   as median_incl,
  max(price_incl)                                           as max_incl,
  count(*) filter (where outcome = 'gewonnen')              as won,
  count(*) filter (where outcome = 'verloren')              as lost,
  count(*) filter (where lost_reason = 'prijs')             as lost_on_price,
  percentile_cont(0.5) within group (order by price_incl)
    filter (where outcome = 'gewonnen')                     as median_won_incl,
  max(quoted_at)                                            as last_quoted_at,
  array_agg(id order by quoted_at desc nulls last)          as quote_ids
from public.whatsapp_quotes
where price_incl is not null
  and review <> 'afgewezen'
group by make, model, (year / 5) * 5, scenario;

comment on view public.whatsapp_price_list is
  'Real quoted prices incl. BTW per make/model/5-year band/scenario, with win/loss. quote_ids open the source rows.';

/*
 * Analysis views. All security_invoker, all skip rows the owner rejected.
 * Every view carries quote_ids so any number opens back to its chats.
 */

/* 1. Funnel per month: how many asked, got a price, bought, said no, went silent, were turned away. */
create or replace view public.whatsapp_funnel
with (security_invoker = true) as
select
  date_trunc('month', asked_at at time zone 'Europe/Amsterdam')::date   as month,
  count(*)                                                               as questions,
  count(*) filter (where price_amount is not null)                      as quoted,
  count(*) filter (where outcome = 'gewonnen')                          as won,
  count(*) filter (where job_id is not null)                            as won_proven_by_job,
  count(*) filter (where outcome = 'verloren')                          as lost,
  count(*) filter (where outcome = 'geen_reactie')                      as silent,
  count(*) filter (where outcome = 'afgewezen_door_ons')                as declined_by_us,
  round(100.0 * count(*) filter (where outcome = 'gewonnen')
        / nullif(count(*) filter (where outcome <> 'onbekend'), 0), 1)  as win_pct,
  array_agg(id)                                                          as quote_ids
from public.whatsapp_quotes
where review <> 'afgewezen'
group by 1;

/* 2. Why the customer said no: price, time, dealer... with their words and the money involved. */
create or replace view public.whatsapp_loss_reasons
with (security_invoker = true) as
select
  coalesce(lost_reason, 'onbekend')                                      as reason,
  scenario,
  count(*)                                                               as lost,
  percentile_cont(0.5) within group (order by price_incl)               as median_our_price_incl,
  percentile_cont(0.5) within group (order by competitor_price)         as median_competitor_price,
  percentile_cont(0.5) within group (order by customer_budget)          as median_customer_budget,
  percentile_cont(0.5) within group (order by reply_minutes)            as median_reply_minutes,
  (array_agg(lost_detail order by asked_at desc) filter (where lost_detail is not null))[1:5]
                                                                         as recent_words,
  array_agg(id order by asked_at desc nulls last)                       as quote_ids
from public.whatsapp_quotes
where review <> 'afgewezen'
  and outcome in ('verloren', 'geen_reactie')
group by 1, 2;

/* 3. Cars and jobs WE turned away: the shopping list for tools, parts and technicians. */
create or replace view public.whatsapp_declined_cars
with (security_invoker = true) as
select
  make,
  model,
  (year / 5) * 5                                                         as year_from,
  scenario,
  declined_reason,
  count(*)                                                               as declined,
  max(asked_at)                                                          as last_asked_at,
  (array_agg(declined_detail order by asked_at desc) filter (where declined_detail is not null))[1:3]
                                                                         as our_words,
  array_agg(id order by asked_at desc nulls last)                       as quote_ids
from public.whatsapp_quotes
where review <> 'afgewezen'
  and outcome = 'afgewezen_door_ons'
group by make, model, (year / 5) * 5, scenario, declined_reason;

/* 4. Does a fast answer win? Win rate per reply-time bucket. */
create or replace view public.whatsapp_reply_speed
with (security_invoker = true) as
select
  case
    when reply_minutes is null then 'onbekend'
    when reply_minutes <= 5    then '0-5 min'
    when reply_minutes <= 15   then '6-15 min'
    when reply_minutes <= 60   then '16-60 min'
    when reply_minutes <= 240  then '1-4 uur'
    else 'later'
  end                                                                    as reply_bucket,
  count(*)                                                               as questions,
  count(*) filter (where outcome = 'gewonnen')                          as won,
  round(100.0 * count(*) filter (where outcome = 'gewonnen')
        / nullif(count(*) filter (where outcome <> 'onbekend'), 0), 1)  as win_pct,
  array_agg(id)                                                          as quote_ids
from public.whatsapp_quotes
where review <> 'afgewezen'
group by 1;

/* 5. When people ask: weekday x hour, Amsterdam time, with win rate. Shows when to be reachable. */
create or replace view public.whatsapp_demand_by_hour
with (security_invoker = true) as
select
  extract(isodow from asked_at at time zone 'Europe/Amsterdam')::int    as weekday,
  extract(hour   from asked_at at time zone 'Europe/Amsterdam')::int    as hour,
  count(*)                                                               as questions,
  count(*) filter (where outcome = 'gewonnen')                          as won,
  count(*) filter (where lost_reason = 'tijd')                          as lost_on_time
from public.whatsapp_quotes
where review <> 'afgewezen' and asked_at is not null
group by 1, 2;

/* 6. Price pushback: where customers argued, what they compared with, and whether lowering helped. */
create or replace view public.whatsapp_price_pressure
with (security_invoker = true) as
select
  make,
  model,
  scenario,
  count(*)                                                               as questions,
  count(*) filter (where price_objection)                               as price_objections,
  count(*) filter (where we_lowered_price)                              as we_lowered,
  count(*) filter (where we_lowered_price and outcome = 'gewonnen')     as lowered_and_won,
  percentile_cont(0.5) within group (order by price_incl)               as median_our_price_incl,
  percentile_cont(0.5) within group (order by competitor_price)         as median_competitor_price,
  array_agg(distinct competitor) filter (where competitor is not null)  as competitors,
  array_agg(id order by asked_at desc nulls last)                       as quote_ids
from public.whatsapp_quotes
where review <> 'afgewezen'
group by make, model, scenario
having count(*) filter (where price_objection) > 0;

notify pgrst, 'reload schema';

-- ===== 0107_webchat_channel.sql =====
/*
 * Webshop chats that the ElevenLabs webhook stored as channel 'unknown'.
 *
 * The chat button on the webshop embeds the ElevenLabs widget, which reports
 * conversation_initiation_source = 'widget' and no phone/whatsapp/sms object.
 * The webhook only knew phone, WhatsApp and SMS, so these landed as 'unknown'
 * and appeared under no channel in Gesprekken. Counted on 21 Nov 2026: 14
 * rows, 27 Oct - 14 Nov. The webhook now files new ones as 'webchat'; this
 * moves the old ones. 'webchat' is the channel the webshop's own assistant
 * (repo shop, src/lib/chat/store.ts) already writes.
 *
 * Only the widget rows. 'react_sdk' and 'unknown' sources are left alone until
 * it is known what they are.
 *
 * Run after 0106. Idempotent.
 */
update public.agent_conversations
   set channel = 'webchat'
 where channel = 'unknown'
   and metadata->>'conversation_initiation_source' = 'widget';

select channel, count(*) from public.agent_conversations group by 1 order by 2 desc;

-- ===== 0108_agent_conversations_agent_id.sql =====
/*
 * Whose agent was it, and was anyone there?
 *
 * ElevenLabs posts every agent in the workspace to one webhook, so the
 * KeyForCars and KEY24 agents' chats arrived in Autosleutel24's Gesprekken as
 * channel 'unknown' (source react_sdk). Checked on 21 Nov 2026 from their
 * summaries: KeyForCars demo chats ("contacted KeyForCars…", "Key for
 * Cars…"), KEY24 tests ("Key twenty-four oto anahtar servisi") and sessions
 * where the agent greeted and nobody answered.
 *
 * From now on the webhook stores agent_id and files any agent not listed in
 * ELEVENLABS_AGENT_IDS as 'extern'. This migration adds the column and sorts
 * the old rows by their summary, since they were stored without an agent id:
 *   extern  another brand's agent, kept but not shown in Gesprekken
 *   leeg    the customer never said anything (one turn, the greeting)
 * What is left as 'unknown' shows under "Overig" for a person to judge.
 *
 * Run after 0107. Idempotent.
 */
alter table public.agent_conversations add column if not exists agent_id text;

update public.agent_conversations
   set channel = 'extern'
 where channel = 'unknown'
   and (summary ilike '%keyforcars%'
     or summary ilike '%key for cars%'
     or summary ilike '%key twenty-four%'
     or summary ilike '%key twenty four%'
     or summary ilike '%key vierentwintig%'
     or summary ilike '%key24%');

update public.agent_conversations
   set channel = 'leeg'
 where channel = 'unknown'
   and jsonb_array_length(coalesce(transcript, '[]'::jsonb)) <= 1;

select channel, count(*) from public.agent_conversations group by 1 order by 2 desc;

-- ===== 0109_my_open_offers.sql =====
-- 0109: a technician's open offers, readable by the technician.
--
-- The Offers screen (/admin/aanbod) read job_offers joined to jobs with the
-- technician's own session. But jobs_monteur_select (0004, widened in 0022)
-- only lets a monteur read jobs *assigned* to them, and an offer is by
-- definition on a job nobody has yet. The join came back empty, so the screen
-- never showed a single offer.
--
-- Opening jobs to every offered technician would hand them the customer's name,
-- phone and street before they accept — exactly what the page comment says
-- must not happen ("the door number is the customer's"). So instead: one
-- function, scoped to the caller, returning only what judging the offer needs
-- (car, work, postcode, town, date). Same shape the page already reads, so the
-- page swaps one query and nothing else.
--
-- Additive: no table, policy or existing function changes. Idempotent.

create or replace function public.crm_my_open_offers()
returns table (
  id          uuid,
  rank        integer,
  score       numeric,
  reason      text,
  offered_at  timestamptz,
  expires_at  timestamptz,
  jobs        jsonb
)
language sql
stable
security definer
set search_path = public
as $$
  select o.id, o.rank, o.score, o.reason, o.offered_at, o.expires_at,
         jsonb_build_object(
           'id', j.id, 'scheduled_date', j.scheduled_date, 'slot_start', j.slot_start, 'slot_end', j.slot_end,
           'postcode', j.postcode, 'city', j.city,
           'car_make', j.car_make, 'car_model', j.car_model, 'car_year', j.car_year,
           'scenario', j.scenario, 'keyless', j.keyless, 'technician_id', j.technician_id
         ) as jobs
    from public.job_offers o
    join public.jobs j on j.id = o.job_id
   where o.technician_id = public.my_technician_id()
     and o.response is null
     and j.technician_id is null
     and o.offered_at <= now()
     and o.expires_at > now()
   order by o.expires_at;
$$;

revoke all on function public.crm_my_open_offers() from public, anon;
grant execute on function public.crm_my_open_offers() to authenticated;

-- ===== 0110_receive_not_on_cancelled_po.sql =====
-- 0110: goods cannot be received on a cancelled purchase order.
--
-- kfc_receive_po_line (0090) never looked at the order's status, so a line of a
-- cancelled order could still be received and the shelf went up for goods that
-- were never meant to come. A draft stays receivable on purpose: the spec allows
-- starting from a direct purchase without placing the order first.
--
-- Same body as 0090 plus the one guard. Replays of an existing receipt key still
-- return the original move, before the guard, so a retry never turns into an error.

create or replace function public.kfc_receive_po_line(
  p_line uuid, p_quantity integer, p_location uuid, p_key text, p_created_by uuid default null
) returns public.kfc_stock_moves language plpgsql as $$
declare v_line public.kfc_purchase_order_lines; v_row public.kfc_stock_moves; v_open integer;
begin
  if p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  select * into v_line from public.kfc_purchase_order_lines where id = p_line for update;
  if not found then raise exception 'KFC_NO_PO_LINE'; end if;
  if exists (select 1 from public.kfc_stock_moves where idempotency_key = p_key) then
    select * into v_row from public.kfc_stock_moves where idempotency_key = p_key; return v_row;
  end if;
  if (select status from public.kfc_purchase_orders where id = v_line.po_id) = 'cancelled' then
    raise exception 'KFC_PO_CANCELLED';
  end if;
  v_row := public.kfc_book_move(v_line.article_code, p_location, p_quantity, 'received', p_key,
    v_line.unit_cost_cents, null, null, p_created_by, null, p_line);
  update public.kfc_purchase_order_lines set received = received + p_quantity where id = p_line;
  if v_line.unit_cost_cents is not null then
    update public.kfc_articles set purchase_price_cents = v_line.unit_cost_cents, updated_at = now() where code = v_line.article_code;
  end if;
  select count(*) into v_open from public.kfc_purchase_order_lines where po_id = v_line.po_id and received < quantity;
  if v_open = 0 then
    update public.kfc_purchase_orders set status = 'received', received_at = now() where id = v_line.po_id and status = 'ordered';
  end if;
  return v_row;
end $$;

revoke all on function public.kfc_receive_po_line(uuid, integer, uuid, text, uuid) from public, anon, authenticated;

-- ===== 0111_purchase_invoice_document.sql =====
-- 0111: a purchase order can carry the supplier's invoice number and the
-- invoice or receipt itself (PDF or photo), so receiving can be checked against
-- the paper and the cost has a source (spec P1-B: "belge fotoğrafı/PDF,
-- tedarikçi, fatura referansı").
--
-- The file lives where the stock photos live (local-data/ locally, the private
-- kfc-stock-photos bucket in production); the row only keeps its name and type.
-- Additive and idempotent: three nullable columns, nothing else changes.

alter table public.kfc_purchase_orders add column if not exists invoice_ref   text;
alter table public.kfc_purchase_orders add column if not exists document_path text;
alter table public.kfc_purchase_orders add column if not exists document_type text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'kfc_purchase_orders_invoice_ref_len') then
    alter table public.kfc_purchase_orders add constraint kfc_purchase_orders_invoice_ref_len check (invoice_ref is null or length(invoice_ref) <= 80);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'kfc_purchase_orders_document_type_check') then
    alter table public.kfc_purchase_orders add constraint kfc_purchase_orders_document_type_check
      check (document_type is null or document_type in ('application/pdf', 'image/jpeg', 'image/png'));
  end if;
end $$;

-- ===== 0112_used_parts_and_assembly.sql =====
-- 0112: second-hand parts and assembly (spec P1-C, scenario S3).
--
-- 1. An article says what it physically is and how it is tracked:
--      condition    new | opened | used
--      tracking     quantity (many identical units on one card)
--                   | serial (one unique unit per card: a used part gets its own card,
--                     and so its own printable internal label)
--      acquisition  purchase | assembly  (how the card came to exist)
--    Defaults keep every existing card exactly as it was: new, quantity, purchase.
--
-- 2. Assembly turns parts into a product in one transaction: each part leaves its
--    shelf (move reason 'assembly', negative), the product arrives on its shelf
--    (reason 'assembly', positive) at a unit cost of parts + labour. Any failure —
--    a part short on its shelf, an unknown article — raises, and Postgres rolls the
--    whole call back, so the ledger never holds half an assembly. A replayed key
--    returns the original assembly and books nothing.
--    A part without a known cost makes the product's cost unknown (null), never
--    zero: the spec forbids publishing a margin that silently assumes free parts.
--
-- Additive: new columns with defaults, one new table, one new function, and the
-- move reason list widened by one value (nothing allowed before is refused now).

alter table public.kfc_articles add column if not exists condition   text not null default 'new';
alter table public.kfc_articles add column if not exists tracking    text not null default 'quantity';
alter table public.kfc_articles add column if not exists acquisition text not null default 'purchase';
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'kfc_articles_condition_check') then
    alter table public.kfc_articles add constraint kfc_articles_condition_check check (condition in ('new', 'opened', 'used'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'kfc_articles_tracking_check') then
    alter table public.kfc_articles add constraint kfc_articles_tracking_check check (tracking in ('quantity', 'serial'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'kfc_articles_acquisition_check') then
    alter table public.kfc_articles add constraint kfc_articles_acquisition_check check (acquisition in ('purchase', 'assembly'));
  end if;
end $$;

alter table public.kfc_stock_moves drop constraint if exists kfc_stock_moves_reason_check;
alter table public.kfc_stock_moves add constraint kfc_stock_moves_reason_check
  check (reason in ('count', 'sale', 'return', 'received', 'transfer', 'correction', 'issue', 'assembly'));

create table if not exists public.kfc_assemblies (
  id               uuid primary key default gen_random_uuid(),
  output_article   text not null references public.kfc_articles (code),
  output_location  uuid not null references public.kfc_locations (id),
  quantity         integer not null check (quantity > 0),
  labour_cents     integer not null default 0 check (labour_cents >= 0),
  unit_cost_cents  integer,           -- null when a part's cost was unknown
  components       jsonb not null,    -- [{article, location, quantity, unit_cost_cents}]
  note             text,
  created_by       uuid,
  created_at       timestamptz not null default now(),
  idempotency_key  text not null unique
);
alter table public.kfc_stock_moves add column if not exists assembly_id uuid references public.kfc_assemblies (id);

create or replace function public.kfc_assemble(
  p_output text, p_output_location uuid, p_quantity integer, p_components jsonb,
  p_labour_cents integer, p_key text, p_created_by uuid default null, p_note text default null
) returns public.kfc_assemblies language plpgsql as $$
declare
  v_row public.kfc_assemblies; v_part jsonb; v_cost integer; v_total bigint := 0; v_unknown boolean := false;
  v_parts jsonb := '[]'::jsonb; v_n integer := 0; v_unit integer;
begin
  select * into v_row from public.kfc_assemblies where idempotency_key = p_key;
  if found then return v_row; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  if coalesce(p_labour_cents, 0) < 0 then raise exception 'KFC_BAD_LABOUR'; end if;
  if jsonb_typeof(p_components) <> 'array' or jsonb_array_length(p_components) = 0 then raise exception 'KFC_NO_COMPONENTS'; end if;
  if not exists (select 1 from public.kfc_articles where code = p_output) then raise exception 'KFC_UNKNOWN_ARTICLE %', p_output; end if;

  insert into public.kfc_assemblies (output_article, output_location, quantity, labour_cents, components, note, created_by, idempotency_key)
  values (p_output, p_output_location, p_quantity, coalesce(p_labour_cents, 0), '[]'::jsonb, p_note, p_created_by, p_key)
  returning * into v_row;

  for v_part in select * from jsonb_array_elements(p_components) loop
    v_n := v_n + 1;
    if (v_part->>'article') = p_output then raise exception 'KFC_PART_IS_OUTPUT'; end if;
    if coalesce((v_part->>'quantity')::integer, 0) <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
    select purchase_price_cents into v_cost from public.kfc_articles where code = v_part->>'article';
    if not found then raise exception 'KFC_UNKNOWN_ARTICLE %', v_part->>'article'; end if;
    if v_cost is null then v_unknown := true; else v_total := v_total + v_cost::bigint * (v_part->>'quantity')::integer; end if;
    -- Parts leave their shelf. kfc_book_move raises KFC_INSUFFICIENT on a short shelf, which undoes everything.
    perform public.kfc_book_move(v_part->>'article', (v_part->>'location')::uuid, -((v_part->>'quantity')::integer), 'assembly',
      p_key || ':in:' || v_n, v_cost, p_note, null, p_created_by);
    update public.kfc_stock_moves set assembly_id = v_row.id where idempotency_key = p_key || ':in:' || v_n;
    v_parts := v_parts || jsonb_build_object('article', v_part->>'article', 'location', v_part->>'location',
      'quantity', (v_part->>'quantity')::integer, 'unit_cost_cents', v_cost);
  end loop;

  v_unit := case when v_unknown then null else round((v_total + coalesce(p_labour_cents, 0)) / p_quantity::numeric)::integer end;
  perform public.kfc_book_move(p_output, p_output_location, p_quantity, 'assembly', p_key || ':out', v_unit, p_note, null, p_created_by);
  update public.kfc_stock_moves set assembly_id = v_row.id where idempotency_key = p_key || ':out';
  update public.kfc_articles set acquisition = 'assembly', purchase_price_cents = coalesce(v_unit, purchase_price_cents), updated_at = now()
   where code = p_output;
  update public.kfc_assemblies set unit_cost_cents = v_unit, components = v_parts where id = v_row.id returning * into v_row;
  return v_row;
end $$;

-- Server-only, like the rest of the stock ledger.
alter table public.kfc_assemblies enable row level security;
revoke all on public.kfc_assemblies from anon, authenticated;
grant all on public.kfc_assemblies to service_role;
revoke all on function public.kfc_assemble(text, uuid, integer, jsonb, integer, text, uuid, text) from public, anon, authenticated;
grant execute on function public.kfc_assemble(text, uuid, integer, jsonb, integer, text, uuid, text) to service_role;

-- ===== 0113_kfc_return_line.sql =====
-- 0113: physical return of a shipped webshop line (spec §4-A, scenario S6).
--
-- Refunds already arrive from the shop as money only (kfc_shop_order_refunds). A
-- returned key coming back onto a shelf had no way in: the "Retour vastleggen"
-- button on the order screen belongs to the old orders table. The spec keeps the
-- two apart: a price refund and a physical return are separate events, and a
-- partial return keeps the original sale price.
--
-- kfc_return_line books the units back (move reason 'return', linked to the order
-- line) onto a chosen shelf, at the cost the sale move was booked at, so stock
-- value stays consistent. It refuses to take back more than was shipped on that
-- line, counting earlier returns. A replayed key returns the original move. The
-- sale move and its price are never touched.
--
-- Additive: one new function, nothing else changes.

create or replace function public.kfc_return_line(
  p_line uuid, p_quantity integer, p_location uuid, p_key text, p_created_by uuid default null, p_note text default null
) returns public.kfc_stock_moves language plpgsql as $$
declare v_line public.kfc_shop_order_lines; v_row public.kfc_stock_moves; v_shipped integer; v_returned integer; v_cost integer;
begin
  select * into v_row from public.kfc_stock_moves where idempotency_key = p_key;
  if found then return v_row; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  if p_location is null then raise exception 'KFC_LOCATION_REQUIRED'; end if;
  select * into v_line from public.kfc_shop_order_lines where id = p_line for update;
  if not found then raise exception 'KFC_NO_ORDER_LINE'; end if;

  select coalesce(-sum(delta), 0), max(unit_cost_cents) into v_shipped, v_cost
    from public.kfc_stock_moves where order_line_id = p_line and reason = 'sale';
  select coalesce(sum(delta), 0) into v_returned
    from public.kfc_stock_moves where order_line_id = p_line and reason = 'return';
  if v_shipped = 0 then raise exception 'KFC_NOT_SHIPPED'; end if;
  if v_returned + p_quantity > v_shipped then raise exception 'KFC_RETURN_EXCEEDS'; end if;

  return public.kfc_book_move(v_line.article_code, p_location, p_quantity, 'return', p_key,
    v_cost, p_note, null, p_created_by, p_line);
end $$;

revoke all on function public.kfc_return_line(uuid, integer, uuid, text, uuid, text) from public, anon, authenticated;
grant execute on function public.kfc_return_line(uuid, integer, uuid, text, uuid, text) to service_role;

-- ===== 0114_job_invoice_snapshot.sql =====
-- Freeze the amounts for a job invoice when the draft is first issued.
create table if not exists public.job_invoice_snapshots (
  invoice_id uuid primary key references public.sales_invoices (id),
  issued_at timestamptz not null default now(),
  lines jsonb not null,
  subtotal numeric not null,
  material_cost numeric,
  technician_cost numeric
);

alter table public.job_invoice_snapshots enable row level security;
revoke all on public.job_invoice_snapshots from public, anon, authenticated;
grant select on public.job_invoice_snapshots to service_role;

create or replace function public.snapshot_issued_job_invoice()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_lines jsonb;
begin
  select jsonb_agg(jsonb_build_object(
    'description', line.description, 'quantity', line.quantity, 'unit_price', line.unit_price,
    'discount', line.discount, 'vat_rate', line.vat_rate
  ) order by line.line_no, line.id)
  into v_lines from public.sales_invoice_lines line where line.invoice_id = new.id;
  if v_lines is null then
    raise exception 'JOB_INVOICE_LINES_REQUIRED';
  end if;

  -- The legacy jobs table defaults unwritten costs to zero.
  insert into public.job_invoice_snapshots (invoice_id, lines, subtotal, material_cost, technician_cost)
  select new.id, v_lines, new.subtotal, nullif(job.cost_materials, 0), nullif(job.cost_technician, 0)
  from public.jobs job where job.id = new.job_id
  on conflict (invoice_id) do nothing;
  return new;
end;
$$;

revoke all on function public.snapshot_issued_job_invoice() from public, anon, authenticated;

create or replace trigger snapshot_issued_job_invoice
after update of status on public.sales_invoices
for each row
when (new.job_id is not null and old.status = 'concept' and new.status in ('verzonden', 'betaald'))
execute function public.snapshot_issued_job_invoice();

-- ===== 0115_shared_job_stock.sql =====
-- Service jobs and webshop orders compete for the same available stock.
create table if not exists public.kfc_job_stock (
  id uuid primary key,
  job_id uuid not null references public.jobs (id) on delete cascade,
  article_code text not null references public.kfc_articles (code),
  quantity integer not null check (quantity > 0),
  state text not null default 'reserved' check (state in ('reserved', 'used', 'released')),
  created_at timestamptz not null default now()
);
create index if not exists kfc_job_stock_article_idx on public.kfc_job_stock (article_code) where state = 'reserved';
create index if not exists kfc_job_stock_job_idx on public.kfc_job_stock (job_id);
alter table public.kfc_job_stock enable row level security;
revoke all on public.kfc_job_stock from public, anon, authenticated;
grant select, insert, update, delete on public.kfc_job_stock to service_role;

create or replace view public.kfc_stock_position as
with located as (
  select l.article_code,
         sum(l.quantity) filter (where loc.kind = 'shelf')      as on_shelf,
         sum(l.quantity) filter (where loc.kind = 'quarantine') as unusable
  from public.kfc_stock_levels l
  join public.kfc_locations loc on loc.id = l.location_id
  group by l.article_code
), unlocated as (
  select article_code, sum(delta) as delta
  from public.kfc_stock_moves where location_id is null group by article_code
), reserved as (
  select article_code, sum(delta) as reserved from (
    select article_code, delta from public.kfc_reservations
    union all
    select article_code, quantity from public.kfc_job_stock where state = 'reserved'
  ) reservations group by article_code
), incoming as (
  select pl.article_code, sum(pl.quantity - pl.received) as incoming
  from public.kfc_purchase_order_lines pl
  join public.kfc_purchase_orders po on po.id = pl.po_id
  where po.status = 'ordered' and pl.quantity > pl.received
  group by pl.article_code
)
select a.code as article_code,
       coalesce(lo.on_shelf, 0) + coalesce(lo.unusable, 0) + coalesce(u.delta, 0) as physical,
       coalesce(lo.unusable, 0)                                                   as unusable,
       coalesce(r.reserved, 0)                                                    as reserved,
       coalesce(lo.on_shelf, 0) + coalesce(u.delta, 0) - coalesce(r.reserved, 0)  as available,
       coalesce(i.incoming, 0)                                                    as incoming
from public.kfc_articles a
left join located   lo on lo.article_code = a.code
left join unlocated u  on u.article_code  = a.code
left join reserved  r  on r.article_code  = a.code
left join incoming  i  on i.article_code  = a.code;

create or replace function public.kfc_reserve_job_stock(p_id uuid, p_job uuid, p_article text, p_quantity integer)
returns public.kfc_job_stock language plpgsql as $$
declare v_job public.jobs; v_row public.kfc_job_stock; v_available bigint;
begin
  select * into v_job from public.jobs where id = p_job for update;
  if not found then raise exception 'KFC_NO_JOB'; end if;
  select * into v_row from public.kfc_job_stock where id = p_id;
  if found then
    if v_row.job_id <> p_job or v_row.article_code <> p_article or v_row.quantity <> p_quantity then
      raise exception 'KFC_RESERVATION_MISMATCH';
    end if;
    return v_row;
  end if;
  if v_job.status in ('geannuleerd', 'afgerond') then raise exception 'KFC_JOB_CLOSED'; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  perform public.kfc_allocate(p_article);
  select least(position.available, coalesce((
    select sum(level.quantity) from public.kfc_stock_levels level join public.kfc_locations location on location.id = level.location_id
    where level.article_code = p_article and location.kind = 'shelf'
  ), 0) - position.reserved) into v_available
  from public.kfc_stock_position position where position.article_code = p_article;
  if not found then raise exception 'KFC_UNKNOWN_ARTICLE'; end if;
  if v_available < p_quantity then raise exception 'KFC_INSUFFICIENT'; end if;
  insert into public.kfc_job_stock (id, job_id, article_code, quantity)
  values (p_id, p_job, p_article, p_quantity) returning * into v_row;
  return v_row;
end $$;

create or replace function public.kfc_finish_job_stock(p_id uuid, p_job uuid, p_location uuid, p_user uuid)
returns public.kfc_job_stock language plpgsql as $$
declare v_job public.jobs; v_row public.kfc_job_stock; v_cost integer;
begin
  select * into v_job from public.jobs where id = p_job for update;
  if not found then raise exception 'KFC_NO_JOB'; end if;
  select * into v_row from public.kfc_job_stock where id = p_id and job_id = p_job for update;
  if not found then raise exception 'KFC_NO_RESERVATION'; end if;
  if v_row.state = (case when p_location is null then 'released' else 'used' end) then return v_row; end if;
  if v_row.state <> 'reserved' then raise exception 'KFC_RESERVATION_CLOSED'; end if;
  if p_location is not null then
    if not exists (select 1 from public.kfc_locations where id = p_location and kind = 'shelf') then
      raise exception 'KFC_LOCATION_REQUIRED';
    end if;
    -- Stock writers lock the level before their move trigger takes the article lock.
    perform public.kfc_lock_level(v_row.article_code, p_location);
  end if;
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || v_row.article_code));
  update public.kfc_job_stock set state = case when p_location is null then 'released' else 'used' end
    where id = p_id returning * into v_row;
  if p_location is null then
    perform public.kfc_allocate(v_row.article_code);
  else
    select purchase_price_cents into v_cost from public.kfc_articles where code = v_row.article_code;
    perform public.kfc_book_move(v_row.article_code, p_location, -v_row.quantity, 'issue',
      'job-stock:' || p_id::text, v_cost, 'Klus ' || p_job::text, null, p_user);
  end if;
  return v_row;
end $$;

-- A webshop shipment may overdraw for legacy orders, but cannot take service-held stock.
create or replace function public.kfc_protect_job_stock()
returns trigger language plpgsql as $$
declare v_available bigint;
begin
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || new.article_code));
  if exists (select 1 from public.kfc_job_stock where article_code = new.article_code and state = 'reserved') then
    select available into v_available from public.kfc_stock_position where article_code = new.article_code;
    if v_available + (case when new.location_id is null then new.delta else 0 end) < 0 then
      raise exception 'KFC_STOCK_RESERVED_FOR_JOB';
    end if;
  end if;
  return new;
end $$;

create or replace trigger kfc_protect_job_stock
before insert on public.kfc_stock_moves
for each row when (new.reason = 'sale' and new.delta < 0)
execute function public.kfc_protect_job_stock();

create or replace function public.kfc_release_cancelled_job_stock()
returns trigger language plpgsql security definer set search_path = '' as $$
declare v_id uuid;
begin
  for v_id in select id from public.kfc_job_stock where job_id = old.id and state = 'reserved' order by article_code, id loop
    perform public.kfc_finish_job_stock(v_id, old.id, null, null);
  end loop;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;

create or replace trigger kfc_release_cancelled_job_stock
after update of status on public.jobs for each row
when (old.status is distinct from new.status and new.status = 'geannuleerd')
execute function public.kfc_release_cancelled_job_stock();

create or replace trigger kfc_release_deleted_job_stock
before delete on public.jobs for each row execute function public.kfc_release_cancelled_job_stock();

revoke all on function public.kfc_reserve_job_stock(uuid, uuid, text, integer) from public, anon, authenticated;
revoke all on function public.kfc_finish_job_stock(uuid, uuid, uuid, uuid) from public, anon, authenticated;
revoke all on function public.kfc_protect_job_stock() from public, anon, authenticated;
revoke all on function public.kfc_release_cancelled_job_stock() from public, anon, authenticated;
grant execute on function public.kfc_reserve_job_stock(uuid, uuid, text, integer) to service_role;
grant execute on function public.kfc_finish_job_stock(uuid, uuid, uuid, uuid) to service_role;

-- ===== 0116_job_invoice_warehouse_cost.sql =====
-- Keep the warehouse issue cost and its source lines when the job invoice is issued.
alter table public.job_invoice_snapshots
  add column if not exists warehouse_materials jsonb not null default '[]'::jsonb;

create or replace function public.snapshot_issued_job_invoice()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_lines jsonb;
  v_warehouse jsonb;
  v_warehouse_cost numeric;
  v_legacy_cost numeric;
begin
  select jsonb_agg(jsonb_build_object(
    'description', line.description, 'quantity', line.quantity, 'unit_price', line.unit_price,
    'discount', line.discount, 'vat_rate', line.vat_rate
  ) order by line.line_no, line.id)
  into v_lines from public.sales_invoice_lines line where line.invoice_id = new.id;
  if v_lines is null then
    raise exception 'JOB_INVOICE_LINES_REQUIRED';
  end if;

  select jsonb_agg(jsonb_build_object(
      'article_code', stock.article_code, 'quantity', stock.quantity, 'unit_cost_cents', move.unit_cost_cents
    ) order by stock.created_at, stock.id),
    case when count(*) = count(move.unit_cost_cents)
      then sum(stock.quantity::numeric * move.unit_cost_cents) / 100 end
  into v_warehouse, v_warehouse_cost
  from public.kfc_job_stock stock
  left join public.kfc_stock_moves move
    on move.idempotency_key = 'job-stock:' || stock.id::text and move.reason = 'issue'
  where stock.job_id = new.job_id and stock.state = 'used';

  select case when count(*) = count(unit_cost)
    then coalesce(sum(quantity * unit_cost), 0) end into v_legacy_cost
  from public.job_materials where job_id = new.job_id;

  -- A manually entered job total may already include warehouse parts.
  insert into public.job_invoice_snapshots (invoice_id, lines, subtotal, material_cost, technician_cost, warehouse_materials)
  select new.id, v_lines, new.subtotal,
    case when v_warehouse is null then nullif(job.cost_materials, 0) else v_warehouse_cost + v_legacy_cost end,
    nullif(job.cost_technician, 0), coalesce(v_warehouse, '[]'::jsonb)
  from public.jobs job where job.id = new.job_id
  on conflict (invoice_id) do nothing;
  return new;
end;
$$;

revoke all on function public.snapshot_issued_job_invoice() from public, anon, authenticated;

-- ===== 0117_job_invoice_line_sources.sql =====
-- Preserve the connection from an invoice line to the actual warehouse usage.
alter table public.sales_invoice_lines
  add column if not exists job_stock_id uuid references public.kfc_job_stock (id) on delete set null,
  add column if not exists job_line_kind text check (job_line_kind in ('product', 'service'));

create or replace function public.validate_job_invoice_line()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.job_stock_id is not null and not exists (
    select 1 from public.kfc_job_stock stock
    join public.sales_invoices invoice on invoice.id = new.invoice_id and invoice.job_id = stock.job_id
    where stock.id = new.job_stock_id and stock.state = 'used'
      and new.job_line_kind = 'product' and new.quantity <= stock.quantity
  ) then
    raise exception 'JOB_INVOICE_INVALID_USAGE';
  end if;
  if new.job_line_kind is not null and not exists (
    select 1 from public.sales_invoices invoice where invoice.id = new.invoice_id and invoice.job_id is not null
  ) then
    raise exception 'JOB_INVOICE_JOB_REQUIRED';
  end if;
  return new;
end;
$$;
revoke all on function public.validate_job_invoice_line() from public, anon, authenticated;
create or replace trigger validate_job_invoice_line
before insert or update on public.sales_invoice_lines
for each row execute function public.validate_job_invoice_line();

create unique index if not exists sales_invoice_lines_job_stock_once
on public.sales_invoice_lines(invoice_id, job_stock_id) where job_stock_id is not null;

create or replace function public.snapshot_issued_job_invoice()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_lines jsonb;
  v_warehouse jsonb;
  v_warehouse_cost numeric;
  v_legacy_cost numeric;
begin
  select jsonb_agg(jsonb_build_object(
    'description', line.description, 'quantity', line.quantity, 'unit_price', line.unit_price,
    'discount', line.discount, 'vat_rate', line.vat_rate,
    'job_stock_id', line.job_stock_id, 'job_line_kind', line.job_line_kind
  ) order by line.line_no, line.id)
  into v_lines from public.sales_invoice_lines line where line.invoice_id = new.id;
  if v_lines is null then
    raise exception 'JOB_INVOICE_LINES_REQUIRED';
  end if;

  select jsonb_agg(jsonb_build_object(
      'article_code', stock.article_code, 'quantity', stock.quantity, 'unit_cost_cents', move.unit_cost_cents
    ) order by stock.created_at, stock.id),
    case when count(*) = count(move.unit_cost_cents)
      then sum(stock.quantity::numeric * move.unit_cost_cents) / 100 end
  into v_warehouse, v_warehouse_cost
  from public.kfc_job_stock stock
  left join public.kfc_stock_moves move
    on move.idempotency_key = 'job-stock:' || stock.id::text and move.reason = 'issue'
  where stock.job_id = new.job_id and stock.state = 'used';

  select case when count(*) = count(unit_cost)
    then coalesce(sum(quantity * unit_cost), 0) end into v_legacy_cost
  from public.job_materials where job_id = new.job_id;

  -- A manually entered job total may already include warehouse parts.
  insert into public.job_invoice_snapshots (invoice_id, lines, subtotal, material_cost, technician_cost, warehouse_materials)
  select new.id, v_lines, new.subtotal,
    case when v_warehouse is null then nullif(job.cost_materials, 0) else v_warehouse_cost + v_legacy_cost end,
    nullif(job.cost_technician, 0), coalesce(v_warehouse, '[]'::jsonb)
  from public.jobs job where job.id = new.job_id
  on conflict (invoice_id) do nothing;
  return new;
end;
$$;

revoke all on function public.snapshot_issued_job_invoice() from public, anon, authenticated;

-- ===== 0118_dispatch_service_price.sql =====
-- Optional service-only amount excluding VAT. Existing package quotes keep their price.
alter table public.dispatch_pricing
  add column if not exists service_price numeric(10,2) check (service_price >= 0);

-- ===== 0119_stock_movement_report.sql =====
-- A single snapshot for report totals and the requested page of movements.
create or replace function public.kfc_stock_movement_report(
  p_from date, p_to date, p_query text default '', p_warehouse text default '', p_page integer default 1
) returns jsonb language sql stable set search_path = '' as $$
with bounds as (
  select p_from::timestamp at time zone 'Europe/Amsterdam' as starts,
    (p_to + 1)::timestamp at time zone 'Europe/Amsterdam' as ends
), scoped as (
  select m.id, m.created_at, m.delta, m.reason, m.quantity_after,
    a.code, a.name, a.sku, loc.warehouse, loc.shelf, loc.box,
    shop_line.order_id, m.sales_invoice_id
  from public.kfc_stock_moves m
  join public.kfc_articles a on a.code = m.article_code
  left join public.kfc_locations loc on loc.id = m.location_id
  left join public.kfc_shop_order_lines shop_line on shop_line.id = m.order_line_id
  cross join bounds
  where m.created_at < bounds.ends
    and (p_warehouse = '' or loc.warehouse = p_warehouse)
    and (p_query = '' or strpos(lower(a.code), lower(p_query)) > 0
      or strpos(lower(a.name), lower(p_query)) > 0 or strpos(lower(a.sku), lower(p_query)) > 0)
), period as (
  select scoped.* from scoped cross join bounds where created_at >= bounds.starts
), totals as (
  select coalesce(sum(delta) filter (where created_at < bounds.starts), 0) as opening,
    coalesce(sum(delta), 0) as closing
  from scoped cross join bounds
), changes as (
  select reason, coalesce(sum(delta) filter (where delta > 0), 0) as incoming,
    coalesce(-sum(delta) filter (where delta < 0), 0) as outgoing
  from period group by reason
)
select jsonb_build_object(
  'opening', totals.opening, 'closing', totals.closing,
  'count', (select count(*) from period),
  'changes', coalesce((select jsonb_agg(to_jsonb(changes) order by reason) from changes), '[]'::jsonb),
  'rows', coalesce((select jsonb_agg(to_jsonb(visible) order by created_at desc, id desc)
    from (select * from period order by created_at desc, id desc limit 25 offset ((greatest(p_page, 1)::bigint - 1) * 25)) visible), '[]'::jsonb)
)
from totals;
$$;

revoke all on function public.kfc_stock_movement_report(date, date, text, text, integer) from public, anon, authenticated;
grant execute on function public.kfc_stock_movement_report(date, date, text, text, integer) to service_role;

-- ===== 0120_customer_account_contacts.sql =====
-- Account classification is explicit. Historical billing records stay unclassified.
alter table public.kfc_customers
  add column if not exists account_kind text check (account_kind in ('person', 'company'));

create table if not exists public.kfc_customer_contacts (
  customer_id uuid not null references public.kfc_customers (id) on delete cascade,
  contact_id uuid not null references public.contacts (id) on delete cascade,
  position text not null check (length(btrim(position)) between 1 and 80),
  primary key (customer_id, contact_id)
);
alter table public.kfc_customer_contacts enable row level security;
revoke all on public.kfc_customer_contacts from public, anon, authenticated;
grant select on public.kfc_customer_contacts to service_role;

create or replace function public.kfc_link_customer_contact(p_customer uuid, p_phone text, p_name text, p_position text)
returns void language plpgsql set search_path = '' as $$
declare
  v_contact public.contacts;
begin
  perform 1 from public.kfc_customers where id = p_customer and account_kind = 'company'
    and merged_into is null and anonymised_at is null for update;
  if not found then raise exception 'CRM_COMPANY_REQUIRED'; end if;
  insert into public.contacts (phone_e164, display_name) values (p_phone, p_name)
    on conflict (phone_e164) do nothing;
  select * into v_contact from public.contacts where phone_e164 = p_phone;
  if not v_contact.active or lower(btrim(v_contact.display_name)) <> lower(btrim(p_name)) then
    raise exception 'CRM_CONTACT_REVIEW';
  end if;
  insert into public.kfc_customer_contacts (customer_id, contact_id, position)
    values (p_customer, v_contact.id, p_position)
    on conflict (customer_id, contact_id) do update set position = excluded.position;
end;
$$;
revoke all on function public.kfc_link_customer_contact(uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.kfc_link_customer_contact(uuid, text, text, text) to service_role;
grant insert, update on public.kfc_customer_contacts to service_role;

-- ===== 0121_job_customer_context.sql =====
-- A billing account and the person handling the job are independent selections.
alter table public.jobs
  add column if not exists billing_account_id uuid references public.kfc_customers(id) on delete set null,
  add column if not exists communication_contact_id uuid,
  add constraint jobs_contact_requires_billing_account
    check (communication_contact_id is null or billing_account_id is not null),
  add constraint jobs_company_contact_membership foreign key (billing_account_id, communication_contact_id)
    references public.kfc_customer_contacts(customer_id, contact_id) on delete set null (communication_contact_id)
    deferrable initially immediate;
create index if not exists jobs_billing_account_idx on public.jobs(billing_account_id);

-- ===== 0122_clear_unlinked_job_contact.sql =====
-- Account deletion clears both references in the same update, also when the
-- billing-account foreign key fires before the membership deletion.
create or replace function public.clear_unlinked_job_contact()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.communication_contact_id := null;
  return new;
end;
$$;
revoke all on function public.clear_unlinked_job_contact() from public, anon, authenticated;
create or replace trigger clear_unlinked_job_contact
before update of billing_account_id on public.jobs
for each row when (old.billing_account_id is not null and new.billing_account_id is null)
execute function public.clear_unlinked_job_contact();

-- ===== 0123_lead_followup.sql =====
-- One open follow-up per lead. Completed tasks remain in the task history.
create unique index if not exists crm_tasks_open_lead_followup
on public.crm_tasks (lead_id) where task_type = 'lead_followup' and completed_at is null;

create or replace function public.crm_open_lead_followup(p_lead uuid)
returns void language plpgsql set search_path = '' as $$
begin
  perform 1 from public.leads where id = p_lead and status = 'new'
    and first_contact_at is null and retracted_at is null for update;
  if not found then raise exception 'CRM_LEAD_NOT_WAITING'; end if;

  insert into public.crm_tasks (lead_id, task_type, description, due_at)
  values (p_lead, 'lead_followup', 'Neem contact op over de aanvraag.', now())
  on conflict (lead_id) where task_type = 'lead_followup' and completed_at is null do nothing;
end;
$$;
revoke all on function public.crm_open_lead_followup(uuid) from public, anon, authenticated;
grant execute on function public.crm_open_lead_followup(uuid) to service_role;

-- ===== 0124_van_stock.sql =====
-- Technician vans hold stock in the same ledger as the central warehouse.
alter table public.kfc_locations
  add column if not exists technician_id uuid references public.technicians(id);
create unique index if not exists kfc_locations_one_van_per_technician
  on public.kfc_locations(technician_id) where technician_id is not null;

create or replace view public.kfc_webshop_position as
select p.article_code, p.available - coalesce(v.quantity, 0) as available, p.incoming
from public.kfc_stock_position p
left join (
  select l.article_code, sum(l.quantity) as quantity from public.kfc_stock_levels l
  join public.kfc_locations loc on loc.id = l.location_id and loc.technician_id is not null
  where loc.kind = 'shelf' group by l.article_code
) v on v.article_code = p.article_code;
revoke all on public.kfc_webshop_position from public, anon, authenticated;
grant select on public.kfc_webshop_position to service_role;

create or replace function public.kfc_allocate(p_article text)
returns void language plpgsql as $$
declare v_avail integer; v_line record; v_take integer;
begin
  if p_article is null then return; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || p_article));
  select available into v_avail from public.kfc_webshop_position where article_code = p_article;
  v_avail := coalesce(v_avail, 0);

  -- Release what orders no longer paid-and-open still hold.
  for v_line in
    select l.id, l.reserved, l.state
      from public.kfc_shop_order_lines l join public.kfc_shop_orders o on o.id = l.order_id
     where l.article_code = p_article and l.reserved > 0
       and not (o.status = 'processing' and o.fulfilment in ('open', 'picked'))
  loop
    insert into public.kfc_reservations (article_code, order_line_id, delta) values (p_article, v_line.id, -v_line.reserved);
    update public.kfc_shop_order_lines
       set reserved = 0, state = case when state = 'shipped' then 'shipped' else 'cancelled' end
     where id = v_line.id;
    v_avail := v_avail + v_line.reserved;
  end loop;

  -- Fill eligible lines, oldest order first.
  for v_line in
    select l.id, l.quantity, l.reserved
      from public.kfc_shop_order_lines l join public.kfc_shop_orders o on o.id = l.order_id
     where l.article_code = p_article and o.status = 'processing' and o.fulfilment in ('open', 'picked')
       and l.state in ('open', 'short', 'reserved') and l.reserved < l.quantity
     order by o.created_at, l.woo_line_id
  loop
    exit when v_avail <= 0;
    v_take := least(v_line.quantity - v_line.reserved, v_avail);
    insert into public.kfc_reservations (article_code, order_line_id, delta) values (p_article, v_line.id, v_take);
    update public.kfc_shop_order_lines
       set reserved = reserved + v_take,
           state = case when reserved + v_take >= quantity then 'reserved' else 'short' end
     where id = v_line.id;
    v_avail := v_avail - v_take;
  end loop;

  -- Whatever is still unfilled is short.
  update public.kfc_shop_order_lines l set state = 'short'
    from public.kfc_shop_orders o
   where o.id = l.order_id and l.article_code = p_article
     and o.status = 'processing' and o.fulfilment in ('open', 'picked')
     and l.state in ('open', 'reserved') and l.reserved < l.quantity;
end $$;

create or replace function public.kfc_ship_order(p_order uuid, p_key text, p_created_by uuid default null)
returns void language plpgsql as $$
declare v_order public.kfc_shop_orders; v_line record; v_loc uuid; v_cost integer;
begin
  select * into v_order from public.kfc_shop_orders where id = p_order for update;
  if not found then raise exception 'KFC_NO_ORDER'; end if;
  if v_order.fulfilment = 'shipped' then return; end if;
  if v_order.status <> 'processing' then raise exception 'KFC_NOT_PAID'; end if;
  for v_line in select * from public.kfc_shop_order_lines where order_id = p_order and state <> 'cancelled' and quantity > 0 loop
    if v_line.article_code is null then
      update public.kfc_shop_order_lines set state = 'shipped' where id = v_line.id;
      continue;
    end if;
    if v_line.reserved > 0 then
      insert into public.kfc_reservations (article_code, order_line_id, delta) values (v_line.article_code, v_line.id, -v_line.reserved);
    end if;
    select l.location_id into v_loc
      from public.kfc_stock_levels l join public.kfc_locations loc on loc.id = l.location_id
     where l.article_code = v_line.article_code and loc.technician_id is null
     order by (loc.kind = 'shelf') desc, l.quantity desc limit 1;
    if v_loc is not null then perform public.kfc_lock_level(v_line.article_code, v_loc); end if;
    if exists (select 1 from public.kfc_stock_levels l join public.kfc_locations loc on loc.id = l.location_id
      where l.article_code = v_line.article_code and loc.technician_id is not null) then
      if v_loc is null or not exists (select 1 from public.kfc_stock_levels level join public.kfc_locations loc on loc.id = level.location_id
        where level.article_code = v_line.article_code and level.location_id = v_loc and loc.kind = 'shelf' and level.quantity >= v_line.quantity)
      then raise exception 'KFC_CENTRAL_STOCK_REQUIRED'; end if;
    end if;
    select purchase_price_cents into v_cost from public.kfc_articles where code = v_line.article_code;
    perform public.kfc_book_move(v_line.article_code, v_loc, -v_line.quantity, 'sale', p_key || ':' || v_line.id::text,
      v_cost, null, null, p_created_by, v_line.id);
    update public.kfc_shop_order_lines set reserved = 0, picked = quantity, state = 'shipped' where id = v_line.id;
  end loop;
  update public.kfc_shop_orders set fulfilment = 'shipped', shipped_at = now(), shipped_by = p_created_by where id = p_order;
end $$;

create or replace function public.kfc_reserve_job_stock(p_id uuid, p_job uuid, p_article text, p_quantity integer)
returns public.kfc_job_stock language plpgsql as $$
declare v_job public.jobs; v_row public.kfc_job_stock; v_available bigint;
begin
  select * into v_job from public.jobs where id = p_job for update;
  if not found then raise exception 'KFC_NO_JOB'; end if;
  select * into v_row from public.kfc_job_stock where id = p_id;
  if found then
    if v_row.job_id <> p_job or v_row.article_code <> p_article or v_row.quantity <> p_quantity then
      raise exception 'KFC_RESERVATION_MISMATCH';
    end if;
    return v_row;
  end if;
  if v_job.status in ('geannuleerd', 'afgerond') then raise exception 'KFC_JOB_CLOSED'; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  perform public.kfc_allocate(p_article);
  select least(position.available, coalesce((
    select sum(level.quantity) from public.kfc_stock_levels level join public.kfc_locations location on location.id = level.location_id
    where level.article_code = p_article and location.kind = 'shelf' and location.technician_id is null
  ), 0) - position.reserved) into v_available
  from public.kfc_stock_position position where position.article_code = p_article;
  if not found then raise exception 'KFC_UNKNOWN_ARTICLE'; end if;
  if v_available < p_quantity then raise exception 'KFC_INSUFFICIENT'; end if;
  insert into public.kfc_job_stock (id, job_id, article_code, quantity)
  values (p_id, p_job, p_article, p_quantity) returning * into v_row;
  return v_row;
end $$;

create or replace function public.kfc_finish_job_stock(p_id uuid, p_job uuid, p_location uuid, p_user uuid)
returns public.kfc_job_stock language plpgsql as $$
declare v_job public.jobs; v_row public.kfc_job_stock; v_cost integer;
begin
  select * into v_job from public.jobs where id = p_job for update;
  if not found then raise exception 'KFC_NO_JOB'; end if;
  select * into v_row from public.kfc_job_stock where id = p_id and job_id = p_job for update;
  if not found then raise exception 'KFC_NO_RESERVATION'; end if;
  if v_row.state = (case when p_location is null then 'released' else 'used' end) then return v_row; end if;
  if v_row.state <> 'reserved' then raise exception 'KFC_RESERVATION_CLOSED'; end if;
  if p_location is not null then
    if not exists (select 1 from public.kfc_locations where id = p_location and kind = 'shelf' and technician_id is null) then
      raise exception 'KFC_LOCATION_REQUIRED';
    end if;
    -- Stock writers lock the level before their move trigger takes the article lock.
    perform public.kfc_lock_level(v_row.article_code, p_location);
  end if;
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || v_row.article_code));
  update public.kfc_job_stock set state = case when p_location is null then 'released' else 'used' end
    where id = p_id returning * into v_row;
  if p_location is null then
    perform public.kfc_allocate(v_row.article_code);
  else
    select purchase_price_cents into v_cost from public.kfc_articles where code = v_row.article_code;
    perform public.kfc_book_move(v_row.article_code, p_location, -v_row.quantity, 'issue',
      'job-stock:' || p_id::text, v_cost, 'Klus ' || p_job::text, null, p_user);
  end if;
  return v_row;
end $$;

create or replace function public.kfc_protect_job_stock()
returns trigger language plpgsql as $$
declare v_available bigint;
begin
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || new.article_code));
  if exists (select 1 from public.kfc_job_stock where article_code = new.article_code and state = 'reserved') then
    select available into v_available from public.kfc_webshop_position where article_code = new.article_code;
    if v_available + (case when new.location_id is null then new.delta else 0 end) < 0 then
      raise exception 'KFC_STOCK_RESERVED_FOR_JOB';
    end if;
  end if;
  return new;
end $$;

-- A single snapshot for report totals and the requested page of movements.
create or replace function public.kfc_stock_movement_report(
  p_from date, p_to date, p_query text default '', p_warehouse text default '', p_page integer default 1
) returns jsonb language sql stable set search_path = '' as $$
with bounds as (
  select p_from::timestamp at time zone 'Europe/Amsterdam' as starts,
    (p_to + 1)::timestamp at time zone 'Europe/Amsterdam' as ends
), scoped as (
  select m.id, m.created_at, m.delta, m.reason, m.quantity_after,
    a.code, a.name, a.sku, loc.warehouse, loc.shelf, loc.box,
    shop_line.order_id, m.sales_invoice_id, job_stock.job_id, tech.name as van_name
  from public.kfc_stock_moves m
  join public.kfc_articles a on a.code = m.article_code
  left join public.kfc_locations loc on loc.id = m.location_id
  left join public.technicians tech on tech.id = loc.technician_id
  left join public.kfc_shop_order_lines shop_line on shop_line.id = m.order_line_id
  left join public.kfc_job_stock job_stock on m.idempotency_key = 'job-stock:' || job_stock.id::text
  cross join bounds
  where m.created_at < bounds.ends
    and (p_warehouse = '' or loc.warehouse = p_warehouse)
    and (p_query = '' or strpos(lower(a.code), lower(p_query)) > 0
      or strpos(lower(a.name), lower(p_query)) > 0 or strpos(lower(a.sku), lower(p_query)) > 0)
), period as (
  select scoped.* from scoped cross join bounds where created_at >= bounds.starts
), totals as (
  select coalesce(sum(delta) filter (where created_at < bounds.starts), 0) as opening,
    coalesce(sum(delta), 0) as closing
  from scoped cross join bounds
), changes as (
  select reason, coalesce(sum(delta) filter (where delta > 0), 0) as incoming,
    coalesce(-sum(delta) filter (where delta < 0), 0) as outgoing
  from period group by reason
)
select jsonb_build_object(
  'opening', totals.opening, 'closing', totals.closing,
  'count', (select count(*) from period),
  'changes', coalesce((select jsonb_agg(to_jsonb(changes) order by reason) from changes), '[]'::jsonb),
  'rows', coalesce((select jsonb_agg(to_jsonb(visible) order by created_at desc, id desc)
    from (select * from period order by created_at desc, id desc limit 25 offset ((greatest(p_page, 1)::bigint - 1) * 25)) visible), '[]'::jsonb)
)
from totals;
$$;

revoke all on function public.kfc_stock_movement_report(date, date, text, text, integer) from public, anon, authenticated;
grant execute on function public.kfc_stock_movement_report(date, date, text, text, integer) to service_role;

-- The source and destination are locked before the allocator, as other ledger writers expect.
create or replace function public.kfc_transfer_van_stock(
  p_id uuid, p_article text, p_central uuid, p_technician uuid, p_quantity integer, p_to_van boolean, p_user uuid
) returns void language plpgsql set search_path = '' as $$
declare v_van uuid; v_from uuid; v_to uuid; v_existing public.kfc_stock_moves;
begin
  if p_id is null or p_quantity <= 0 or p_quantity is null or p_to_van is null then raise exception 'KFC_BAD_TRANSFER'; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_van_transfer:' || p_id::text));
  if not exists (select 1 from public.kfc_locations where id = p_central and warehouse = 'main' and kind = 'shelf' and technician_id is null)
  then raise exception 'KFC_LOCATION_REQUIRED'; end if;
  if not exists (select 1 from public.technicians where id = p_technician and (active or not p_to_van))
  then raise exception 'KFC_BAD_VAN'; end if;
  insert into public.kfc_locations(warehouse, shelf, box, technician_id)
    values ('van', upper(p_technician::text), 'STOCK', p_technician)
    on conflict (technician_id) where technician_id is not null do nothing;
  select id into v_van from public.kfc_locations where technician_id = p_technician;
  v_from := case when p_to_van then p_central else v_van end;
  v_to := case when p_to_van then v_van else p_central end;
  perform public.kfc_lock_level(p_article, least(v_from,v_to));
  perform public.kfc_lock_level(p_article, greatest(v_from,v_to));
  perform pg_advisory_xact_lock(hashtext('kfc_alloc:' || p_article));
  select * into v_existing from public.kfc_stock_moves where idempotency_key = 'van-transfer:' || p_id::text || ':out';
  if found then
    if v_existing.article_code <> p_article or v_existing.location_id <> v_from or v_existing.delta <> -p_quantity
      or not exists(select 1 from public.kfc_stock_moves where idempotency_key = 'van-transfer:' || p_id::text || ':in' and location_id = v_to)
    then raise exception 'KFC_RESERVATION_MISMATCH'; end if;
    return;
  end if;
  if p_to_van and (select available from public.kfc_webshop_position where article_code = p_article) < p_quantity
  then raise exception 'KFC_INSUFFICIENT'; end if;
  perform public.kfc_transfer(p_article,v_from,v_to,p_quantity,'van-transfer:' || p_id::text,p_user);
end $$;

create or replace function public.kfc_use_van_stock(
  p_id uuid, p_job uuid, p_article text, p_location uuid, p_quantity integer, p_user uuid
) returns void language plpgsql set search_path = '' as $$
declare v_job public.jobs; v_existing public.kfc_job_stock; v_cost integer;
begin
  select * into v_job from public.jobs where id = p_job for update;
  if not found or not exists (
    select 1 from public.technicians tech join public.kfc_locations loc on loc.technician_id = tech.id
    where tech.id = v_job.technician_id and tech.user_id = p_user and loc.id = p_location
  ) then raise exception 'KFC_BAD_VAN'; end if;
  select * into v_existing from public.kfc_job_stock where id = p_id;
  if found then
    if v_existing.job_id <> p_job or v_existing.article_code <> p_article or v_existing.quantity <> p_quantity
      or not exists (select 1 from public.kfc_stock_moves where idempotency_key = 'job-stock:' || p_id::text and location_id = p_location)
    then raise exception 'KFC_RESERVATION_MISMATCH'; end if;
    return;
  end if;
  if v_job.status = 'geannuleerd' or exists (select 1 from public.sales_invoices where job_id = p_job and status <> 'concept')
  then raise exception 'KFC_JOB_CLOSED'; end if;
  if p_quantity is null or p_quantity <= 0 then raise exception 'KFC_BAD_QUANTITY'; end if;
  select purchase_price_cents into v_cost from public.kfc_articles where code = p_article;
  if not found then raise exception 'KFC_UNKNOWN_ARTICLE'; end if;
  insert into public.kfc_job_stock(id,job_id,article_code,quantity,state) values (p_id,p_job,p_article,p_quantity,'used');
  perform public.kfc_book_move(p_article,p_location,-p_quantity,'issue','job-stock:' || p_id::text,v_cost,'Klus ' || p_job::text,null,p_user);
end $$;
revoke all on function public.kfc_transfer_van_stock(uuid,text,uuid,uuid,integer,boolean,uuid) from public, anon, authenticated;
revoke all on function public.kfc_use_van_stock(uuid,uuid,text,uuid,integer,uuid) from public, anon, authenticated;
grant execute on function public.kfc_transfer_van_stock(uuid,text,uuid,uuid,integer,boolean,uuid) to service_role;
grant execute on function public.kfc_use_van_stock(uuid,uuid,text,uuid,integer,uuid) to service_role;

create or replace function public.snapshot_issued_job_invoice()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  v_lines jsonb;
  v_warehouse jsonb;
  v_warehouse_cost numeric;
  v_legacy_cost numeric;
begin
  perform 1 from public.jobs where id = new.job_id for no key update;
  select jsonb_agg(jsonb_build_object(
    'description', line.description, 'quantity', line.quantity, 'unit_price', line.unit_price,
    'discount', line.discount, 'vat_rate', line.vat_rate,
    'job_stock_id', line.job_stock_id, 'job_line_kind', line.job_line_kind
  ) order by line.line_no, line.id)
  into v_lines from public.sales_invoice_lines line where line.invoice_id = new.id;
  if v_lines is null then
    raise exception 'JOB_INVOICE_LINES_REQUIRED';
  end if;

  select jsonb_agg(jsonb_build_object(
      'article_code', stock.article_code, 'quantity', stock.quantity, 'unit_cost_cents', move.unit_cost_cents
    ) order by stock.created_at, stock.id),
    case when count(*) = count(move.unit_cost_cents)
      then sum(stock.quantity::numeric * move.unit_cost_cents) / 100 end
  into v_warehouse, v_warehouse_cost
  from public.kfc_job_stock stock
  left join public.kfc_stock_moves move
    on move.idempotency_key = 'job-stock:' || stock.id::text and move.reason = 'issue'
  where stock.job_id = new.job_id and stock.state = 'used';

  select case when count(*) = count(unit_cost)
    then coalesce(sum(quantity * unit_cost), 0) end into v_legacy_cost
  from public.job_materials where job_id = new.job_id;

  -- A manually entered job total may already include warehouse parts.
  insert into public.job_invoice_snapshots (invoice_id, lines, subtotal, material_cost, technician_cost, warehouse_materials)
  select new.id, v_lines, new.subtotal,
    case when v_warehouse is null then nullif(job.cost_materials, 0) else v_warehouse_cost + v_legacy_cost end,
    nullif(job.cost_technician, 0), coalesce(v_warehouse, '[]'::jsonb)
  from public.jobs job where job.id = new.job_id
  on conflict (invoice_id) do nothing;
  return new;
end;
$$;

revoke all on function public.snapshot_issued_job_invoice() from public, anon, authenticated;

-- ===== 0125_quick_article.sql =====
create or replace function public.kfc_quick_article(
  p_prefix text, p_name text, p_sku text, p_ean text, p_condition text
) returns text language plpgsql set search_path = '' as $$
declare
  v_code text;
  v_matches integer;
  v_next bigint;
begin
  if p_prefix not in ('KFC-3-', 'AS24-3-') or p_condition not in ('new','opened','used')
    then raise exception 'KFC_BAD_CARD'; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_quick_article'));
  if p_condition <> 'used' then
    select min(code), count(*) into v_code, v_matches from public.kfc_articles
      where tracking = 'quantity' and ((p_sku <> '' and upper(sku) = upper(p_sku)) or p_ean = any(ean));
    if v_matches > 1 then raise exception 'KFC_AMBIGUOUS_CARD'; end if;
    if v_matches = 1 then return v_code; end if;
  end if;
  select coalesce(max(substr(code,length(p_prefix)+1)::bigint),0)+1 into v_next
    from public.kfc_articles where code ~ ('^' || p_prefix || '[0-9]{1,18}$');
  v_code := p_prefix || v_next::text;
  insert into public.kfc_articles(code,name,sku,ean,category,condition,tracking)
    values(v_code,p_name,p_sku,case when p_ean is null then array[]::text[] else array[p_ean] end,
      'Werkplaats',p_condition,case when p_condition = 'used' then 'serial' else 'quantity' end);
  return v_code;
end $$;
revoke all on function public.kfc_quick_article(text,text,text,text,text) from public,anon,authenticated;
grant execute on function public.kfc_quick_article(text,text,text,text,text) to service_role;

-- ===== 0126_supplier_reference.sql =====
alter table public.kfc_articles add column if not exists supplier_ref text;
create or replace function public.kfc_quick_article_details(
  p_prefix text, p_name text, p_sku text, p_ean text, p_condition text, p_ref text, p_category text, p_tracking text, p_cost integer
) returns text language plpgsql set search_path = '' as $$
declare
  v_code text;
  v_matches integer;
  v_next bigint;
begin
  if p_prefix not in ('KFC-3-', 'AS24-3-') or p_condition not in ('new','opened','used')
    then raise exception 'KFC_BAD_CARD'; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_quick_article'));
  if p_tracking = 'quantity' then
    select min(code), count(*) into v_code, v_matches from public.kfc_articles
      where tracking = 'quantity' and ((p_sku <> '' and upper(sku) = upper(p_sku)) or p_ean = any(ean) or (p_ref <> '' and upper(supplier_ref) = upper(p_ref)));
    if v_matches > 1 then raise exception 'KFC_AMBIGUOUS_CARD'; end if;
    if v_matches = 1 then return v_code; end if;
  end if;
  select coalesce(max(substr(code,length(p_prefix)+1)::bigint),0)+1 into v_next
    from public.kfc_articles where code ~ ('^' || p_prefix || '[0-9]{1,18}$');
  v_code := p_prefix || v_next::text;
  insert into public.kfc_articles(code,name,sku,ean,category,condition,tracking,supplier_ref,purchase_price_cents)
    values(v_code,p_name,p_sku,case when p_ean is null then array[]::text[] else array[p_ean] end,
      p_category,p_condition,p_tracking,nullif(p_ref,''),p_cost);
  return v_code;
end $$;
revoke all on function public.kfc_quick_article_details(text,text,text,text,text,text,text,text,integer) from public,anon,authenticated;
grant execute on function public.kfc_quick_article_details(text,text,text,text,text,text,text,text,integer) to service_role;

-- ===== 0127_receipt_photo.sql =====
create table public.kfc_receipt_photos (
  move_id bigint primary key references public.kfc_stock_moves(id) on delete cascade,
  mime text not null check (mime in ('image/jpeg','image/png')),
  content bytea not null check (octet_length(content) between 1 and 2097152)
);
alter table public.kfc_receipt_photos enable row level security;
revoke all on public.kfc_receipt_photos from public,anon,authenticated;
grant select,insert,delete on public.kfc_receipt_photos to service_role;

create function public.kfc_receive_with_photo(p_line uuid,p_quantity integer,p_location uuid,p_key text,p_created_by uuid,p_photo text,p_mime text)
returns bigint language plpgsql set search_path='' as $$
declare l public.kfc_purchase_order_lines; m public.kfc_stock_moves;
begin
  perform pg_advisory_xact_lock(hashtext('receipt:' || p_key));
  select * into l from public.kfc_purchase_order_lines where id=p_line for update;
  if not found then raise exception 'KFC_NO_PO_LINE'; end if;
  select * into m from public.kfc_stock_moves where idempotency_key=p_key;
  if found then
    if m.purchase_order_line_id is distinct from p_line or m.delta<>p_quantity or m.location_id is distinct from p_location
      then raise exception 'KFC_RECEIPT_CONFLICT'; end if;
    if p_photo is not null and not exists(select 1 from public.kfc_receipt_photos where move_id=m.id and content=decode(p_photo,'base64') and mime=p_mime)
      then raise exception 'KFC_RECEIPT_CONFLICT'; end if;
    return m.id;
  end if;
  if l.received+p_quantity>l.quantity or (select status from public.kfc_purchase_orders where id=l.po_id)<>'ordered'
    then raise exception 'KFC_RECEIPT_CONFLICT'; end if;
  m:=public.kfc_receive_po_line(p_line,p_quantity,p_location,p_key,p_created_by);
  if p_photo is not null then insert into public.kfc_receipt_photos values(m.id,p_mime,decode(p_photo,'base64')); end if;
  return m.id;
end $$;
revoke all on function public.kfc_receive_with_photo(uuid,integer,uuid,text,uuid,text,text) from public,anon,authenticated;
grant execute on function public.kfc_receive_with_photo(uuid,integer,uuid,text,uuid,text,text) to service_role;

-- ===== 0128_purchase_expense.sql =====
-- One aggregated non-stock expense per purchase document. Stock lines stay on the order.
alter table public.expenses add column purchase_order_id uuid unique references public.kfc_purchase_orders(id);
create policy linked_purchase_expense_office on public.expenses as restrictive for all to authenticated
  using (purchase_order_id is null or public.crm_role() in ('owner','kantoor'))
  with check (purchase_order_id is null or public.crm_role() in ('owner','kantoor'));

-- ===== 0129_kfc_pos.sql =====
/*
 * Kassa (point of sale) for the shop counter.
 *
 * A till session is opened with a cash float and closed with a counted amount;
 * the difference against what the session's cash sales say should be in the
 * drawer is the Z-report. One sale is one call to kfc_pos_sale, which in a
 * single transaction:
 *
 *   - writes a paid sales invoice (shelf prices are incl. VAT; the invoice
 *     stores lines and totals excl. VAT + VAT, like every other invoice),
 *   - books a 'sale' stock move per line through kfc_book_move, linked to the
 *     invoice, taken from the bin that holds the most of that article,
 *   - records the payments (cash / pin / other) against the session,
 *   - and, when a known customer is chosen, settles the ledger entry the
 *     kfc_post_invoice trigger just posted, so their balance stays at zero.
 *
 * Retry-safe: p_key is the client's id for the sale. A second call with the
 * same key returns the invoice already made instead of selling twice.
 *
 * Server-only like the other kfc_* tables: RLS on, no policies, no grants.
 */

create table if not exists public.kfc_pos_sessions (
  id                   uuid primary key default gen_random_uuid(),
  register             text not null default 'winkel',
  opened_at            timestamptz not null default now(),
  opened_by            uuid,
  opening_float_cents  integer not null default 0 check (opening_float_cents >= 0),
  closed_at            timestamptz,
  closed_by            uuid,
  expected_cash_cents  integer,
  counted_cash_cents   integer check (counted_cash_cents is null or counted_cash_cents >= 0),
  note                 text
);

-- One open session per till.
create unique index if not exists kfc_pos_sessions_one_open
  on public.kfc_pos_sessions (register) where closed_at is null;

alter table public.sales_invoices
  add column if not exists pos_session_id uuid references public.kfc_pos_sessions (id),
  add column if not exists pos_key text;

create unique index if not exists sales_invoices_pos_key on public.sales_invoices (pos_key) where pos_key is not null;
create index if not exists sales_invoices_pos_session on public.sales_invoices (pos_session_id) where pos_session_id is not null;

create table if not exists public.kfc_pos_payments (
  id                bigserial primary key,
  session_id        uuid not null references public.kfc_pos_sessions (id),
  sales_invoice_id  uuid not null references public.sales_invoices (id) on delete restrict,
  method            text not null check (method in ('cash', 'pin', 'other')),
  -- What stays in the till / on the terminal: for cash, tendered minus change.
  amount_cents      integer not null check (amount_cents > 0),
  tendered_cents    integer not null check (tendered_cents >= amount_cents),
  created_at        timestamptz not null default now(),
  created_by        uuid,
  idempotency_key   text not null unique
);

create index if not exists kfc_pos_payments_session on public.kfc_pos_payments (session_id);

-- ---------------------------------------------------------------------------
-- Open / close
-- ---------------------------------------------------------------------------

create or replace function public.kfc_pos_open(p_register text, p_float_cents integer, p_opened_by uuid)
returns public.kfc_pos_sessions language plpgsql as $$
declare v_row public.kfc_pos_sessions;
begin
  if p_float_cents is null or p_float_cents < 0 or p_float_cents > 10000000 then raise exception 'KFC_POS_BAD_FLOAT'; end if;
  select * into v_row from public.kfc_pos_sessions where register = p_register and closed_at is null;
  if found then return v_row; end if;
  insert into public.kfc_pos_sessions (register, opening_float_cents, opened_by)
  values (p_register, p_float_cents, p_opened_by)
  returning * into v_row;
  return v_row;
exception when unique_violation then
  select * into v_row from public.kfc_pos_sessions where register = p_register and closed_at is null;
  return v_row;
end $$;

create or replace function public.kfc_pos_close(p_session uuid, p_counted_cents integer, p_note text, p_closed_by uuid)
returns public.kfc_pos_sessions language plpgsql as $$
declare v_row public.kfc_pos_sessions; v_cash integer;
begin
  if p_counted_cents is null or p_counted_cents < 0 or p_counted_cents > 100000000 then raise exception 'KFC_POS_BAD_COUNT'; end if;
  select * into v_row from public.kfc_pos_sessions where id = p_session for update;
  if not found then raise exception 'KFC_POS_NO_SESSION'; end if;
  if v_row.closed_at is not null then return v_row; end if;
  select coalesce(sum(amount_cents), 0) into v_cash from public.kfc_pos_payments where session_id = p_session and method = 'cash';
  update public.kfc_pos_sessions
     set closed_at = now(), closed_by = p_closed_by, counted_cash_cents = p_counted_cents,
         expected_cash_cents = v_row.opening_float_cents + v_cash, note = nullif(trim(coalesce(p_note, '')), '')
   where id = p_session
  returning * into v_row;
  return v_row;
end $$;

-- ---------------------------------------------------------------------------
-- One sale
-- ---------------------------------------------------------------------------
--
-- p_lines:    [{ "article": "AS24-1-...", "quantity": 2, "unit_price_cents": 1995,
--                "discount_cents": 0, "vat_rate": 21 }, ...]   prices incl. VAT
-- p_payments: [{ "method": "cash", "tendered_cents": 5000 }, { "method": "pin", "tendered_cents": 1990 }]
-- p_biller:   { "name": ..., "street": ..., "postcode": ..., "city": ..., "email": ...,
--               "phone": ..., "kvk": ..., "btw": ..., "iban": ... }

create or replace function public.kfc_pos_sale(
  p_session uuid, p_key text, p_lines jsonb, p_payments jsonb,
  p_customer uuid, p_client_name text, p_biller jsonb, p_created_by uuid
) returns uuid language plpgsql as $$
declare
  v_invoice uuid; v_session public.kfc_pos_sessions;
  v_line jsonb; v_pay jsonb; v_i integer := 0;
  v_article public.kfc_articles; v_qty integer; v_price integer; v_disc integer; v_rate numeric;
  v_incl integer; v_total integer := 0; v_vat numeric := 0;
  v_cash integer := 0; v_noncash integer := 0; v_change integer;
  v_method text; v_tendered integer; v_location uuid; v_number text;
begin
  if p_key is null or length(p_key) < 8 or length(p_key) > 80 then raise exception 'KFC_POS_BAD_KEY'; end if;

  -- Retry: the same sale again returns the invoice it already made.
  select id into v_invoice from public.sales_invoices where pos_key = p_key;
  if found then return v_invoice; end if;

  select * into v_session from public.kfc_pos_sessions where id = p_session for update;
  if not found or v_session.closed_at is not null then raise exception 'KFC_POS_CLOSED'; end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 or jsonb_array_length(p_lines) > 200 then
    raise exception 'KFC_POS_BAD_LINES';
  end if;
  if jsonb_typeof(p_payments) <> 'array' or jsonb_array_length(p_payments) = 0 or jsonb_array_length(p_payments) > 10 then
    raise exception 'KFC_POS_BAD_PAYMENTS';
  end if;

  -- Validate every line and work out the totals before writing anything.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    if not found then raise exception 'KFC_POS_UNKNOWN_ARTICLE'; end if;
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    if v_qty is null or v_qty < 1 or v_qty > 10000 or v_price is null or v_price < 0 or v_price > 10000000
       or v_disc < 0 or v_disc > v_qty * v_price or v_rate not in (0, 9, 21) then
      raise exception 'KFC_POS_BAD_LINES';
    end if;
    v_incl := v_qty * v_price - v_disc;
    v_total := v_total + v_incl;
    v_vat := v_vat + v_incl - v_incl / (1 + v_rate / 100);
  end loop;

  -- Payments: non-cash is taken as entered; cash may exceed what is left (change).
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method not in ('cash', 'pin', 'other') or v_tendered is null or v_tendered <= 0 or v_tendered > 100000000 then
      raise exception 'KFC_POS_BAD_PAYMENTS';
    end if;
    if v_method = 'cash' then v_cash := v_cash + v_tendered; else v_noncash := v_noncash + v_tendered; end if;
  end loop;
  if v_noncash > v_total then raise exception 'KFC_POS_OVERPAID'; end if;
  if v_cash + v_noncash < v_total then raise exception 'KFC_POS_UNDERPAID'; end if;
  v_change := v_cash + v_noncash - v_total;

  insert into public.sales_invoices (
    biller_name, biller_street, biller_postcode, biller_city, biller_email, biller_phone, biller_kvk, biller_btw, biller_iban,
    client_name, notes, subtotal, vat_total, total, status, paid_at, created_by, customer_id, pos_session_id, pos_key
  ) values (
    coalesce(nullif(p_biller->>'name', ''), 'Winkel'), p_biller->>'street', p_biller->>'postcode', p_biller->>'city',
    p_biller->>'email', p_biller->>'phone', p_biller->>'kvk', p_biller->>'btw', p_biller->>'iban',
    coalesce(nullif(trim(coalesce(p_client_name, '')), ''), 'Kassaverkoop'), 'Kassa',
    round((v_total - round(v_vat)) / 100.0, 2), round(round(v_vat) / 100.0, 2), round(v_total / 100.0, 2),
    'betaald', now(), p_created_by, p_customer, p_session, p_key
  ) returning id, invoice_number into v_invoice, v_number;

  -- Lines (excl. VAT per unit) and the stock moves.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_i := v_i + 1;
    select * into v_article from public.kfc_articles where code = v_line->>'article';
    v_qty := (v_line->>'quantity')::integer;
    v_price := (v_line->>'unit_price_cents')::integer;
    v_disc := coalesce((v_line->>'discount_cents')::integer, 0);
    v_rate := coalesce((v_line->>'vat_rate')::numeric, 21);
    insert into public.sales_invoice_lines (invoice_id, line_no, description, quantity, unit_price, discount, vat_rate)
    values (v_invoice, v_i,
      left(v_article.name || case when v_article.sku <> '' then ' (' || v_article.sku || ')' else '' end, 300),
      v_qty, round(v_price / (1 + v_rate / 100) / 100.0, 2), round(v_disc / (1 + v_rate / 100) / 100.0, 2), v_rate);

    v_location := null;
    select location_id into v_location from public.kfc_stock_levels
     where article_code = v_article.code order by quantity desc, location_id limit 1;
    perform public.kfc_book_move(v_article.code, v_location, -v_qty, 'sale', p_key || ':line:' || v_i,
      null, 'Kassa ' || v_number, null, p_created_by, null, null, null, v_invoice);
  end loop;

  -- Payments: cash keeps tendered minus change.
  v_i := 0;
  for v_pay in select * from jsonb_array_elements(p_payments) loop
    v_i := v_i + 1;
    v_method := v_pay->>'method';
    v_tendered := (v_pay->>'tendered_cents')::integer;
    if v_method = 'cash' then
      if v_change >= v_tendered then v_change := v_change - v_tendered; continue; end if;
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, 'cash', v_tendered - v_change, v_tendered, p_created_by, p_key || ':pay:' || v_i);
      v_change := 0;
    else
      insert into public.kfc_pos_payments (session_id, sales_invoice_id, method, amount_cents, tendered_cents, created_by, idempotency_key)
      values (p_session, v_invoice, v_method, v_tendered, v_tendered, p_created_by, p_key || ':pay:' || v_i);
    end if;
  end loop;

  -- A known customer: the trigger posted the invoice to their ledger; settle it now.
  if p_customer is not null and v_total > 0 then
    perform public.kfc_post_entry(p_customer, 'payment', v_total, p_key || ':ledger', null, 'Kassa ' || v_number,
      p_created_by, null, v_invoice);
  end if;

  return v_invoice;
end $$;

-- ---------------------------------------------------------------------------
-- Security: server-only.
-- ---------------------------------------------------------------------------

alter table public.kfc_pos_sessions enable row level security;
alter table public.kfc_pos_payments enable row level security;
revoke all on public.kfc_pos_sessions from anon, authenticated;
revoke all on public.kfc_pos_payments from anon, authenticated;
revoke all on function public.kfc_pos_open(text, integer, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_close(uuid, integer, text, uuid) from public, anon, authenticated;
revoke all on function public.kfc_pos_sale(uuid, text, jsonb, jsonb, uuid, text, jsonb, uuid) from public, anon, authenticated;

-- ===== 0130_kfc_cariler.sql =====
-- ============================================================================
-- 0130: cariler — customer and supplier accounts, purchasing on supplier
-- accounts (Nebim V3 / ERPNext style: Customer, Supplier, Purchase Order,
-- Purchase Receipt, Purchase Invoice, statement, aging).
--
--   kfc_customers              + kvk, invoice_email, iban, bic, website
--                              (company accounts need KvK and BTW; the app
--                              validates, the database keeps the KvK format).
--   kfc_suppliers              the supplier account (crediteur).
--   kfc_supplier_contacts      people at the supplier.
--   kfc_purchase_orders        + supplier_id, backfilled from the free-text
--                              supplier names (the text column stays as the
--                              name on the order).
--   kfc_supplier_articles      supplier SKU, agreed price, lead time, minimum
--                              quantity, preferred supplier; last price paid
--                              is kept up to date from purchase order lines.
--   kfc_supplier_ledger        append-only, mirrors kfc_customer_ledger (0093):
--                              invoice (+), payment (−), credit_note (−),
--                              refund (+), opening (±), write_off (−),
--                              reversal (opposite). amount_cents > 0 means
--                              we owe the supplier.
--   kfc_supplier_allocations   which payment/credit settles which invoice.
--   kfc_supplier_invoice_open  open remainder per invoice entry.
--   kfc_supplier_balance       open, overdue, aging and open purchase orders.
--   kfc_purchase_line_facts    one row per purchase order line, for reports.
--
--   kfc_post_supplier_entry    books an invoice, payment, credit, refund,
--                              opening or write-off; idempotent on p_key;
--                              credits allocate oldest due first.
--   kfc_reverse_supplier_entry the opposite entry and opposite allocations.
--
-- Server-only like 0090/0093: RLS on, nothing for anon/authenticated.
-- Idempotent: safe to run twice.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- Customers: company registration and invoicing fields
-- ---------------------------------------------------------------------------
alter table public.kfc_customers add column if not exists kvk text;
alter table public.kfc_customers add column if not exists invoice_email text;
alter table public.kfc_customers add column if not exists iban text;
alter table public.kfc_customers add column if not exists bic text;
alter table public.kfc_customers add column if not exists website text;

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'kfc_customers_kvk_format') then
    alter table public.kfc_customers add constraint kfc_customers_kvk_format check (kvk is null or kvk ~ '^[0-9]{8}$');
  end if;
end $$;
create index if not exists kfc_customers_kvk_idx on public.kfc_customers (kvk) where kvk is not null;
create index if not exists kfc_customers_vat_idx on public.kfc_customers (upper(vat_number)) where vat_number is not null;

-- ---------------------------------------------------------------------------
-- Suppliers
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_suppliers (
  id                uuid primary key default gen_random_uuid(),
  name              text not null check (length(btrim(name)) between 1 and 160),
  kvk               text check (kvk is null or kvk ~ '^[0-9]{8}$'),
  vat_number        text,
  iban              text,
  bic               text,
  email             text,
  order_email       text,
  phone             text,
  website           text,
  contact_name      text,
  street            text,
  postcode          text,
  city              text,
  country           text not null default 'NL',
  terms_days        integer not null default 30 check (terms_days between 0 and 180),
  lead_time_days    integer check (lead_time_days is null or lead_time_days between 0 and 365),
  min_order_cents   integer check (min_order_cents is null or min_order_cents >= 0),
  customer_number   text,  -- our account number at this supplier
  note              text,
  active            boolean not null default true,
  created_by        uuid,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create unique index if not exists kfc_suppliers_name_key on public.kfc_suppliers (lower(btrim(name)));
create index if not exists kfc_suppliers_active_idx on public.kfc_suppliers (active, lower(name));

create table if not exists public.kfc_supplier_contacts (
  id           uuid primary key default gen_random_uuid(),
  supplier_id  uuid not null references public.kfc_suppliers (id) on delete cascade,
  name         text not null check (length(btrim(name)) between 1 and 120),
  position     text,
  email        text,
  phone        text,
  created_at   timestamptz not null default now()
);
create index if not exists kfc_supplier_contacts_supplier_idx on public.kfc_supplier_contacts (supplier_id);

-- ---------------------------------------------------------------------------
-- Purchase orders on the supplier account
-- ---------------------------------------------------------------------------
alter table public.kfc_purchase_orders add column if not exists supplier_id uuid references public.kfc_suppliers (id);
create index if not exists kfc_purchase_orders_supplier_idx on public.kfc_purchase_orders (supplier_id, created_at desc);

-- Backfill: one supplier per distinct (case- and space-insensitive) name.
insert into public.kfc_suppliers (name)
select distinct on (lower(btrim(supplier))) btrim(supplier)
  from public.kfc_purchase_orders
 where supplier_id is null and btrim(coalesce(supplier, '')) <> ''
 order by lower(btrim(supplier)), created_at
on conflict (lower(btrim(name))) do nothing;

update public.kfc_purchase_orders po
   set supplier_id = s.id
  from public.kfc_suppliers s
 where po.supplier_id is null
   and lower(btrim(po.supplier)) = lower(btrim(s.name));

-- ---------------------------------------------------------------------------
-- Supplier articles: what this supplier sells us, under which code, at what price
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_supplier_articles (
  supplier_id       uuid not null references public.kfc_suppliers (id) on delete cascade,
  article_code      text not null references public.kfc_articles (code) on delete cascade,
  supplier_sku      text,
  price_cents       integer check (price_cents is null or price_cents >= 0),
  min_qty           integer not null default 1 check (min_qty > 0),
  lead_time_days    integer check (lead_time_days is null or lead_time_days between 0 and 365),
  preferred         boolean not null default false,
  last_price_cents  integer,
  last_ordered_at   timestamptz,
  note              text,
  updated_at        timestamptz not null default now(),
  primary key (supplier_id, article_code)
);
create index if not exists kfc_supplier_articles_article_idx on public.kfc_supplier_articles (article_code);
create index if not exists kfc_supplier_articles_sku_idx on public.kfc_supplier_articles (upper(supplier_sku)) where supplier_sku is not null;
create unique index if not exists kfc_supplier_articles_one_preferred on public.kfc_supplier_articles (article_code) where preferred;

-- A priced purchase order line keeps the supplier-article row current: last
-- price paid, last ordered; the agreed price is only filled when still empty.
create or replace function public.kfc_supplier_article_from_po_line() returns trigger
language plpgsql set search_path = '' as $$
declare v_supplier uuid;
begin
  select supplier_id into v_supplier from public.kfc_purchase_orders where id = new.po_id;
  if v_supplier is null then return new; end if;
  insert into public.kfc_supplier_articles as sa (supplier_id, article_code, price_cents, last_price_cents, last_ordered_at)
  values (v_supplier, new.article_code, new.unit_cost_cents, new.unit_cost_cents, now())
  on conflict (supplier_id, article_code) do update
    set last_price_cents = coalesce(excluded.last_price_cents, sa.last_price_cents),
        price_cents      = coalesce(sa.price_cents, excluded.price_cents),
        last_ordered_at  = now(),
        updated_at       = now();
  return new;
end $$;
drop trigger if exists kfc_supplier_article_from_po_line on public.kfc_purchase_order_lines;
create trigger kfc_supplier_article_from_po_line after insert or update of unit_cost_cents on public.kfc_purchase_order_lines
  for each row execute function public.kfc_supplier_article_from_po_line();

-- Existing priced lines seed the table once (latest price per supplier and article).
insert into public.kfc_supplier_articles (supplier_id, article_code, price_cents, last_price_cents, last_ordered_at)
select distinct on (po.supplier_id, l.article_code) po.supplier_id, l.article_code, l.unit_cost_cents, l.unit_cost_cents, coalesce(po.ordered_at, po.created_at)
  from public.kfc_purchase_order_lines l
  join public.kfc_purchase_orders po on po.id = l.po_id
 where po.supplier_id is not null
 order by po.supplier_id, l.article_code, (l.unit_cost_cents is null), coalesce(po.ordered_at, po.created_at) desc
on conflict (supplier_id, article_code) do nothing;

-- ---------------------------------------------------------------------------
-- Supplier ledger (crediteuren), mirroring the customer ledger of 0093/0094
-- ---------------------------------------------------------------------------
create table if not exists public.kfc_supplier_ledger (
  id                 bigserial primary key,
  supplier_id        uuid not null references public.kfc_suppliers (id),
  entry_type         text not null check (entry_type in ('invoice', 'payment', 'credit_note', 'refund', 'opening', 'write_off', 'reversal')),
  amount_cents       integer not null,
  vat_cents          integer not null default 0,
  entry_date         date not null default (now() at time zone 'Europe/Amsterdam')::date,
  due_date           date,
  booked_at          timestamptz not null default now(),
  invoice_ref        text,
  purchase_order_id  uuid references public.kfc_purchase_orders (id) on delete set null,
  reverses_entry_id  bigint references public.kfc_supplier_ledger (id),
  note               text,
  created_by         uuid,
  idempotency_key    text not null unique
);
create index if not exists kfc_supplier_ledger_supplier_idx on public.kfc_supplier_ledger (supplier_id, entry_date desc, booked_at desc, id desc);
create index if not exists kfc_supplier_ledger_po_idx on public.kfc_supplier_ledger (purchase_order_id) where purchase_order_id is not null;
create index if not exists kfc_supplier_ledger_reverses_idx on public.kfc_supplier_ledger (reverses_entry_id) where reverses_entry_id is not null;

create table if not exists public.kfc_supplier_allocations (
  id                bigserial primary key,
  credit_entry_id   bigint not null references public.kfc_supplier_ledger (id),
  invoice_entry_id  bigint not null references public.kfc_supplier_ledger (id),
  amount_cents      integer not null,
  created_at        timestamptz not null default now()
);
create index if not exists kfc_supplier_alloc_invoice_idx on public.kfc_supplier_allocations (invoice_entry_id);
create index if not exists kfc_supplier_alloc_credit_idx on public.kfc_supplier_allocations (credit_entry_id);

-- Open remainder of every debit entry we still owe (invoice, opening, refund).
-- Reversals and reversed entries are never open themselves (as 0094).
create or replace view public.kfc_supplier_invoice_open as
select e.id as entry_id, e.supplier_id, e.entry_type, e.entry_date, e.due_date, e.invoice_ref, e.purchase_order_id, e.amount_cents,
       e.amount_cents - coalesce((select sum(a.amount_cents) from public.kfc_supplier_allocations a where a.invoice_entry_id = e.id), 0) as open_cents
  from public.kfc_supplier_ledger e
 where e.amount_cents > 0
   and e.entry_type <> 'reversal'
   and not exists (select 1 from public.kfc_supplier_ledger r where r.reverses_entry_id = e.id);

-- Balance, aging by due date and open purchase orders, per supplier.
create or replace view public.kfc_supplier_balance as
with open as (
  select supplier_id,
         sum(open_cents) filter (where open_cents > 0 and (due_date is null or due_date >= current_date)) as not_due,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 1 and 30)  as d1_30,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 31 and 60) as d31_60,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date between 61 and 90) as d61_90,
         sum(open_cents) filter (where open_cents > 0 and current_date - due_date > 90)              as d90p,
         min(due_date) filter (where open_cents > 0 and due_date < current_date) as oldest_overdue
    from public.kfc_supplier_invoice_open group by supplier_id
), bal as (
  select supplier_id, sum(amount_cents) as open_cents, max(entry_date) as last_entry from public.kfc_supplier_ledger group by supplier_id
), lines as (
  select po_id, sum(greatest(quantity - received, 0)::bigint * coalesce(unit_cost_cents, 0)) as open_value
    from public.kfc_purchase_order_lines group by po_id
), po as (
  select o.supplier_id,
         count(*) filter (where o.status in ('draft', 'ordered')) as open_pos,
         count(*) filter (where o.status = 'ordered' and o.expected_on < current_date) as late_pos,
         coalesce(sum(l.open_value) filter (where o.status = 'ordered'), 0) as on_order_cents,
         max(coalesce(o.ordered_at, o.created_at)) as last_order_at
    from public.kfc_purchase_orders o
    left join lines l on l.po_id = o.id
   where o.supplier_id is not null
   group by o.supplier_id
)
select s.id as supplier_id,
       coalesce(b.open_cents, 0) as open_cents,
       coalesce(o.d1_30, 0) + coalesce(o.d31_60, 0) + coalesce(o.d61_90, 0) + coalesce(o.d90p, 0) as overdue_cents,
       coalesce(o.not_due, 0) as not_due, coalesce(o.d1_30, 0) as d1_30, coalesce(o.d31_60, 0) as d31_60,
       coalesce(o.d61_90, 0) as d61_90, coalesce(o.d90p, 0) as d90p, o.oldest_overdue, b.last_entry,
       coalesce(p.open_pos, 0) as open_pos, coalesce(p.late_pos, 0) as late_pos,
       coalesce(p.on_order_cents, 0) as on_order_cents, p.last_order_at
  from public.kfc_suppliers s
  left join open o on o.supplier_id = s.id
  left join bal  b on b.supplier_id = s.id
  left join po   p on p.supplier_id = s.id;

-- One row per purchase order line: purchases per supplier / period / article,
-- open orders, late deliveries and purchase price history all read this.
create or replace view public.kfc_purchase_line_facts as
select l.id as line_id, o.id as po_id, o.status, o.supplier_id, coalesce(s.name, o.supplier) as supplier_name,
       o.created_at, o.ordered_at, o.expected_on, o.received_at, o.invoice_ref,
       (coalesce(o.ordered_at, o.created_at) at time zone 'Europe/Amsterdam')::date as order_date,
       l.article_code, a.name as article_name, a.sku, a.category,
       l.quantity, l.received, greatest(l.quantity - l.received, 0) as open_quantity, l.unit_cost_cents,
       l.quantity::bigint * l.unit_cost_cents as ordered_cents,
       l.received::bigint * l.unit_cost_cents as received_cents,
       (select max(m.created_at) from public.kfc_stock_moves m where m.purchase_order_line_id = l.id and m.reason = 'received') as last_receipt_at
  from public.kfc_purchase_order_lines l
  join public.kfc_purchase_orders o on o.id = l.po_id
  left join public.kfc_articles a on a.code = l.article_code
  left join public.kfc_suppliers s on s.id = o.supplier_id;

-- ---------------------------------------------------------------------------
-- Booking
-- ---------------------------------------------------------------------------
-- p_allocations: [{"invoice_entry_id": 12, "amount_cents": 5000}] or null for oldest-due-first.
create or replace function public.kfc_post_supplier_entry(
  p_supplier uuid, p_type text, p_amount_cents integer, p_key text,
  p_entry_date date default null, p_due_date date default null, p_invoice_ref text default null,
  p_purchase_order uuid default null, p_vat_cents integer default 0, p_note text default null,
  p_created_by uuid default null, p_allocations jsonb default null
) returns bigint language plpgsql set search_path = '' as $$
declare
  v_id bigint; v_signed integer; v_left integer; v_inv record; v_take integer; v_alloc jsonb;
  v_terms integer; v_date date; v_ref text; v_po_supplier uuid;
begin
  if p_type not in ('invoice', 'payment', 'credit_note', 'refund', 'opening', 'write_off') then raise exception 'KFC_BAD_TYPE'; end if;
  if p_type <> 'opening' and (p_amount_cents is null or p_amount_cents <= 0) then raise exception 'KFC_BAD_AMOUNT'; end if;
  if p_type = 'opening' and coalesce(p_amount_cents, 0) = 0 then raise exception 'KFC_BAD_AMOUNT'; end if;
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;

  perform pg_advisory_xact_lock(hashtext('kfc_supplier_ledger:' || p_supplier::text));
  -- A retry that raced the first attempt finds its entry after the lock.
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  select terms_days into v_terms from public.kfc_suppliers where id = p_supplier;
  if not found then raise exception 'KFC_NO_SUPPLIER'; end if;

  v_date := coalesce(p_entry_date, (now() at time zone 'Europe/Amsterdam')::date);
  v_ref := nullif(btrim(coalesce(p_invoice_ref, '')), '');

  if p_purchase_order is not null then
    select supplier_id into v_po_supplier from public.kfc_purchase_orders where id = p_purchase_order;
    if not found then raise exception 'KFC_NO_PO'; end if;
    if v_po_supplier is distinct from p_supplier then raise exception 'KFC_PO_SUPPLIER'; end if;
  end if;

  if p_type = 'invoice' then
    if v_ref is null then raise exception 'KFC_INVOICE_REF'; end if;
    if exists (select 1 from public.kfc_supplier_ledger e
                where e.supplier_id = p_supplier and e.entry_type = 'invoice' and lower(e.invoice_ref) = lower(v_ref)
                  and not exists (select 1 from public.kfc_supplier_ledger r where r.reverses_entry_id = e.id)) then
      raise exception 'KFC_DUPLICATE_INVOICE';
    end if;
  end if;

  v_signed := case when p_type in ('payment', 'credit_note', 'write_off') then -p_amount_cents else p_amount_cents end;
  insert into public.kfc_supplier_ledger (supplier_id, entry_type, amount_cents, vat_cents, entry_date, due_date, invoice_ref, purchase_order_id, note, created_by, idempotency_key)
  values (p_supplier, p_type, v_signed, case when p_type = 'invoice' then coalesce(p_vat_cents, 0) else 0 end, v_date,
          case when p_type in ('invoice', 'opening', 'refund') then coalesce(p_due_date, v_date + coalesce(v_terms, 30)) end,
          v_ref, p_purchase_order, nullif(btrim(coalesce(p_note, '')), ''), p_created_by, p_key)
  returning id into v_id;

  -- The supplier's invoice number lands on the order when the order has none yet.
  if p_type = 'invoice' and p_purchase_order is not null then
    update public.kfc_purchase_orders set invoice_ref = v_ref where id = p_purchase_order and invoice_ref is null;
  end if;

  if v_signed >= 0 then return v_id; end if;

  v_left := -v_signed;
  if p_allocations is not null then
    for v_alloc in select * from jsonb_array_elements(p_allocations) loop
      v_take := least((v_alloc->>'amount_cents')::integer, v_left);
      exit when v_take is null or v_take <= 0;
      select o.entry_id, o.open_cents into v_inv from public.kfc_supplier_invoice_open o
       where o.entry_id = (v_alloc->>'invoice_entry_id')::bigint and o.supplier_id = p_supplier;
      if not found then raise exception 'KFC_BAD_ALLOCATION'; end if;
      v_take := least(v_take, greatest(v_inv.open_cents, 0));
      continue when v_take <= 0;
      insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_id, v_inv.entry_id, v_take);
      v_left := v_left - v_take;
    end loop;
  end if;
  -- Whatever the explicit allocations did not use goes oldest due first.
  for v_inv in select entry_id, open_cents from public.kfc_supplier_invoice_open
                where supplier_id = p_supplier and open_cents > 0
                order by due_date nulls last, entry_date, entry_id loop
    exit when v_left <= 0;
    v_take := least(v_inv.open_cents, v_left);
    insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_id, v_inv.entry_id, v_take);
    v_left := v_left - v_take;
  end loop;
  return v_id;
end $$;

create or replace function public.kfc_reverse_supplier_entry(p_entry bigint, p_key text, p_created_by uuid default null, p_note text default null)
returns bigint language plpgsql set search_path = '' as $$
declare v_orig public.kfc_supplier_ledger; v_id bigint; v_a record;
begin
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  select * into v_orig from public.kfc_supplier_ledger where id = p_entry;
  if not found then raise exception 'KFC_NO_ENTRY'; end if;
  perform pg_advisory_xact_lock(hashtext('kfc_supplier_ledger:' || v_orig.supplier_id::text));
  select id into v_id from public.kfc_supplier_ledger where idempotency_key = p_key;
  if found then return v_id; end if;
  if v_orig.entry_type = 'reversal' then raise exception 'KFC_ALREADY_REVERSED'; end if;
  if exists (select 1 from public.kfc_supplier_ledger where reverses_entry_id = p_entry) then raise exception 'KFC_ALREADY_REVERSED'; end if;
  insert into public.kfc_supplier_ledger (supplier_id, entry_type, amount_cents, vat_cents, entry_date, invoice_ref, purchase_order_id, reverses_entry_id, note, created_by, idempotency_key)
  values (v_orig.supplier_id, 'reversal', -v_orig.amount_cents, -v_orig.vat_cents, (now() at time zone 'Europe/Amsterdam')::date,
          v_orig.invoice_ref, v_orig.purchase_order_id, p_entry, coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Tegenboeking van #' || p_entry::text), p_created_by, p_key)
  returning id into v_id;
  for v_a in select * from public.kfc_supplier_allocations where credit_entry_id = p_entry or invoice_entry_id = p_entry loop
    insert into public.kfc_supplier_allocations (credit_entry_id, invoice_entry_id, amount_cents) values (v_a.credit_entry_id, v_a.invoice_entry_id, -v_a.amount_cents);
  end loop;
  return v_id;
end $$;

-- ---------------------------------------------------------------------------
-- Server only
-- ---------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array['kfc_suppliers', 'kfc_supplier_contacts', 'kfc_supplier_articles', 'kfc_supplier_ledger', 'kfc_supplier_allocations'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from public, anon, authenticated', t);
    execute format('grant all on public.%I to service_role', t);
  end loop;
end $$;
revoke all on public.kfc_supplier_invoice_open from public, anon, authenticated;
revoke all on public.kfc_supplier_balance from public, anon, authenticated;
revoke all on public.kfc_purchase_line_facts from public, anon, authenticated;
grant select on public.kfc_supplier_invoice_open, public.kfc_supplier_balance, public.kfc_purchase_line_facts to service_role;
grant usage, select on sequence public.kfc_supplier_ledger_id_seq, public.kfc_supplier_allocations_id_seq to service_role;
revoke all on function public.kfc_post_supplier_entry(uuid, text, integer, text, date, date, text, uuid, integer, text, uuid, jsonb) from public, anon, authenticated;
revoke all on function public.kfc_reverse_supplier_entry(bigint, text, uuid, text) from public, anon, authenticated;
revoke all on function public.kfc_supplier_article_from_po_line() from public, anon, authenticated;
grant execute on function public.kfc_post_supplier_entry(uuid, text, integer, text, date, date, text, uuid, integer, text, uuid, jsonb) to service_role;
grant execute on function public.kfc_reverse_supplier_entry(bigint, text, uuid, text) to service_role;

notify pgrst, 'reload schema';

-- ===== 0131_kfc_inventory_reports.sql =====
-- ============================================================================
-- 0131: KeyForCars inventory lists and owner reports (Nebim / ERPNext level).
--
-- Read-only views and report functions over the ledger of 0090 and later. Nothing
-- here writes stock; every number is derived from kfc_stock_moves,
-- kfc_stock_levels, kfc_purchase_order_lines and the documents a move links to.
--
--   kfc_article_overview     one row per article: master data, the five stock
--                            numbers, minimum, value at purchase price, last
--                            supplier, last receipt / sale, sales 30 / 90 / 365
--                            days and a stock state (negatief · nul · laag ·
--                            op_voorraad). The article master list pages,
--                            filters and sorts on this view through PostgREST.
--   kfc_sales_lines          every 'sale' and 'return' move as a sales line with
--                            channel (webshop · kassa · factuur · overig), revenue
--                            excl. VAT and cost. Returns are negative lines.
--   kfc_sales_report()       sales per article / category / day / month / channel
--   kfc_article_movement()   per article: stock, sold, revenue, profit, cover days
--                            (slow / fast movers and ABC)
--   kfc_stock_valuation()    quantity and value per article and location on a date
--   kfc_stock_ledger()       every move with a running balance per article
--   kfc_stock_ageing()       FIFO ageing of the current stock in day buckets
--   kfc_article_totals()     counts and stock value for the article list header
--
-- Revenue rules (also in docs/voorraad-rapporten.md):
--   webshop  the order line's total excl. VAT, pro rata the moved quantity;
--   invoice  (kassa and other invoices) the invoice line whose description is the
--            article name (+ " (SKU)"), as kfc_pos_sale writes it; when no line
--            matches, the article's shelf price / 1.21 and the row is flagged
--            revenue_estimated;
--   cost     the move's unit_cost_cents, else the article's current purchase
--            price (flagged cost_estimated).
--
-- Install isolation: these objects only read tables of the database they are
-- created in; KeyForCars and Autosleutel24 each run their own Supabase project.
--
-- Server-only like 0090: nothing for anon or authenticated, select / execute for
-- service_role only. Idempotent: create or replace / if not exists throughout.
-- ============================================================================

-- Indexes the reports filter on -----------------------------------------------
create index if not exists kfc_stock_moves_reason_time_idx on public.kfc_stock_moves (reason, created_at);
create index if not exists kfc_stock_moves_invoice_idx on public.kfc_stock_moves (sales_invoice_id) where sales_invoice_id is not null;
create index if not exists kfc_stock_moves_order_line_idx on public.kfc_stock_moves (order_line_id) where order_line_id is not null;
create index if not exists kfc_stock_moves_location_time_idx on public.kfc_stock_moves (location_id, created_at);
create index if not exists kfc_stock_moves_batch_idx on public.kfc_stock_moves (count_batch_id) where count_batch_id is not null;
create index if not exists kfc_articles_category_idx on public.kfc_articles (category);
create index if not exists kfc_articles_status_idx on public.kfc_articles (status);

-- ---------------------------------------------------------------------------
-- Sales lines
-- ---------------------------------------------------------------------------
create or replace view public.kfc_sales_lines as
select
  m.id                                                   as move_id,
  m.created_at,
  (m.created_at at time zone 'Europe/Amsterdam')::date   as day,
  m.article_code,
  a.name,
  a.sku,
  a.category,
  m.reason,
  -m.delta                                               as quantity,  -- sale +, return −
  case
    when m.order_line_id is not null then 'webshop'
    when m.sales_invoice_id is not null and coalesce(m.note, '') like 'Kassa %' then 'kassa'
    when m.sales_invoice_id is not null then 'factuur'
    else 'overig'
  end                                                    as channel,
  so.shop,
  coalesce(so.number, si.invoice_number)                 as document,
  m.order_line_id,
  m.sales_invoice_id,
  case
    when sl.id is not null and sl.quantity > 0
      then round(coalesce(sl.total_excl_cents, 0)::numeric * (-m.delta) / sl.quantity)::bigint
    when il.unit_price is not null
      then round((il.unit_price * il.quantity - il.discount) / il.quantity * 100 * (-m.delta))::bigint
    else round(coalesce(a.sale_price_cents, 0)::numeric / 1.21 * (-m.delta))::bigint
  end                                                    as revenue_cents,
  (sl.id is null and il.unit_price is null)              as revenue_estimated,
  (coalesce(m.unit_cost_cents, a.purchase_price_cents, 0)::bigint * (-m.delta)) as cost_cents,
  (m.unit_cost_cents is null)                            as cost_estimated
from public.kfc_stock_moves m
join public.kfc_articles a on a.code = m.article_code
left join public.kfc_shop_order_lines sl on sl.id = m.order_line_id
left join public.kfc_shop_orders so on so.id = sl.order_id
left join public.sales_invoices si on si.id = m.sales_invoice_id
left join lateral (
  select l.unit_price, l.quantity, l.discount
  from public.sales_invoice_lines l
  where m.sales_invoice_id is not null and l.invoice_id = m.sales_invoice_id
    and l.description in (a.name, left(a.name || case when a.sku <> '' then ' (' || a.sku || ')' else '' end, 300))
  order by l.line_no
  limit 1
) il on true
where m.reason in ('sale', 'return');

-- ---------------------------------------------------------------------------
-- Article overview (master list)
-- ---------------------------------------------------------------------------
create or replace view public.kfc_article_overview as
with levels as (
  select l.article_code,
         sum(l.minimum) filter (where loc.kind = 'shelf')                                   as minimum,
         array_agg(distinct loc.warehouse) filter (where l.quantity <> 0)                   as warehouses,
         array_agg(distinct loc.warehouse || '/' || loc.shelf || '/' || loc.box)
           filter (where l.quantity <> 0)                                                    as locations,
         max(l.last_counted_at)                                                              as last_counted_at
  from public.kfc_stock_levels l
  join public.kfc_locations loc on loc.id = l.location_id
  group by l.article_code
), moves as (
  select article_code,
         max(created_at) filter (where reason in ('received', 'assembly') and delta > 0) as last_received_at,
         max(created_at) filter (where reason = 'sale')                                  as last_sold_at,
         max(created_at)                                                                  as last_move_at,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '30 days'), 0)  as sold_30d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '90 days'), 0)  as sold_90d,
         coalesce(-sum(delta) filter (where reason in ('sale', 'return') and created_at >= now() - interval '365 days'), 0) as sold_365d
  from public.kfc_stock_moves
  group by article_code
), suppliers as (
  select pl.article_code,
         array_agg(distinct po.supplier)                                                   as suppliers,
         (array_agg(po.supplier order by coalesce(po.ordered_at, po.created_at) desc))[1]  as last_supplier,
         (array_agg(pl.unit_cost_cents order by coalesce(po.ordered_at, po.created_at) desc)
            filter (where pl.unit_cost_cents is not null))[1]                              as last_po_cost_cents
  from public.kfc_purchase_order_lines pl
  join public.kfc_purchase_orders po on po.id = pl.po_id
  where po.status <> 'cancelled'
  group by pl.article_code
)
select
  a.code, a.name, a.sku, a.ean, a.category, a.status, a.condition, a.tracking, a.supplier_ref,
  a.sale_price_cents, a.purchase_price_cents, a.photo_version, a.created_at, a.updated_at,
  p.physical, p.unusable, p.reserved, p.available, p.incoming,
  coalesce(lv.minimum, 0)::integer                                                   as minimum,
  (greatest(p.physical - p.unusable, 0)::bigint * coalesce(a.purchase_price_cents, 0)) as stock_value_cents,
  (a.purchase_price_cents is null)                                                   as unpriced,
  coalesce(lv.warehouses, '{}')                                                      as warehouses,
  coalesce(lv.locations, '{}')                                                       as locations,
  lv.last_counted_at,
  coalesce(s.suppliers, '{}')                                                        as suppliers,
  s.last_supplier,
  s.last_po_cost_cents,
  mv.last_received_at, mv.last_sold_at, mv.last_move_at,
  coalesce(mv.sold_30d, 0)::integer  as sold_30d,
  coalesce(mv.sold_90d, 0)::integer  as sold_90d,
  coalesce(mv.sold_365d, 0)::integer as sold_365d,
  case
    when p.physical < 0 then 'negatief'
    when p.physical = 0 then 'nul'
    when coalesce(lv.minimum, 0) > 0 and p.available <= lv.minimum then 'laag'
    else 'op_voorraad'
  end as stock_state,
  case when a.sale_price_cents is null or a.purchase_price_cents is null or a.sale_price_cents = 0 then null
       else round((a.sale_price_cents / 1.21 - a.purchase_price_cents) / (a.sale_price_cents / 1.21) * 100, 1)
  end as margin_pct
from public.kfc_articles a
join public.kfc_stock_position p on p.article_code = a.code
left join levels lv on lv.article_code = a.code
left join moves mv on mv.article_code = a.code
left join suppliers s on s.article_code = a.code;

-- ---------------------------------------------------------------------------
-- Sales report: grouped sales lines for a period.
-- p_group: article · category · day · month · channel · shop
-- ---------------------------------------------------------------------------
create or replace function public.kfc_sales_report(
  p_from date, p_to date, p_group text default 'article',
  p_category text default '', p_channel text default '', p_query text default ''
) returns table (
  key text, label text, category text, quantity bigint, lines bigint,
  revenue_cents bigint, cost_cents bigint, profit_cents bigint, margin_pct numeric,
  estimated bigint, first_at timestamptz, last_at timestamptz
) language sql stable set search_path = '' as $$
  with scoped as (
    select s.*,
      case p_group
        when 'category' then coalesce(nullif(s.category, ''), '(geen categorie)')
        when 'day'      then to_char(s.day, 'YYYY-MM-DD')
        when 'month'    then to_char(s.day, 'YYYY-MM')
        when 'channel'  then s.channel
        when 'shop'     then coalesce(s.shop, s.channel)
        else s.article_code
      end as k
    from public.kfc_sales_lines s
    where s.day between p_from and p_to
      and (p_category = '' or s.category = p_category)
      and (p_channel = '' or s.channel = p_channel)
      and (p_query = '' or strpos(lower(s.article_code), lower(p_query)) > 0
           or strpos(lower(s.name), lower(p_query)) > 0 or strpos(lower(s.sku), lower(p_query)) > 0)
  )
  select k,
    case when p_group = 'article' then max(name) else k end,
    case when p_group = 'article' then max(category) else null end,
    sum(quantity)::bigint, count(*)::bigint,
    sum(revenue_cents)::bigint, sum(cost_cents)::bigint, (sum(revenue_cents) - sum(cost_cents))::bigint,
    case when sum(revenue_cents) = 0 then null
         else round((sum(revenue_cents) - sum(cost_cents))::numeric / sum(revenue_cents) * 100, 1) end,
    count(*) filter (where revenue_estimated or cost_estimated)::bigint,
    min(created_at), max(created_at)
  from scoped
  group by k
  order by case when p_group in ('day', 'month') then k end, sum(revenue_cents) desc;
$$;

-- ---------------------------------------------------------------------------
-- Article movement: slow / fast movers and ABC (classification done in the app).
-- ---------------------------------------------------------------------------
create or replace function public.kfc_article_movement(p_from date, p_to date, p_category text default '')
returns table (
  code text, name text, sku text, category text, status text,
  physical integer, available integer, stock_value_cents bigint,
  sold bigint, revenue_cents bigint, profit_cents bigint,
  last_sold_at timestamptz, last_received_at timestamptz, days_cover numeric
) language sql stable set search_path = '' as $$
  with sales as (
    select article_code, sum(quantity)::bigint as sold, sum(revenue_cents)::bigint as revenue,
           (sum(revenue_cents) - sum(cost_cents))::bigint as profit
    from public.kfc_sales_lines
    where day between p_from and p_to
    group by article_code
  )
  select o.code, o.name, o.sku, o.category, o.status,
    o.physical::integer, o.available::integer, o.stock_value_cents,
    coalesce(s.sold, 0), coalesce(s.revenue, 0), coalesce(s.profit, 0),
    o.last_sold_at, o.last_received_at,
    case when coalesce(s.sold, 0) <= 0 then null
         else round(o.physical::numeric / (s.sold::numeric / greatest(p_to - p_from + 1, 1)), 0) end
  from public.kfc_article_overview o
  left join sales s on s.article_code = o.code
  where (p_category = '' or o.category = p_category)
    and (o.physical <> 0 or s.article_code is not null);
$$;

-- ---------------------------------------------------------------------------
-- Stock valuation on a date (end of that day, Amsterdam), per article and
-- location, from the ledger. Value at the last known unit cost on that date
-- (receipts / assemblies), else the current purchase price. Quarantine stock
-- is listed with value 0.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_valuation(p_date date, p_warehouse text default '', p_category text default '')
returns table (
  article_code text, name text, sku text, category text,
  location_id uuid, warehouse text, shelf text, box text, kind text, technician_id uuid,
  quantity bigint, unit_cost_cents integer, value_cents bigint, cost_estimated boolean
) language sql stable set search_path = '' as $$
  with bound as (select (p_date + 1)::timestamp at time zone 'Europe/Amsterdam' as ends),
  qty as (
    select m.article_code, m.location_id, sum(m.delta)::bigint as quantity
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends
    group by m.article_code, m.location_id
    having sum(m.delta) <> 0
  ), cost as (
    select distinct on (m.article_code) m.article_code, m.unit_cost_cents
    from public.kfc_stock_moves m cross join bound
    where m.created_at < bound.ends and m.delta > 0 and m.reason in ('received', 'assembly')
      and m.unit_cost_cents is not null
    order by m.article_code, m.created_at desc, m.id desc
  )
  select q.article_code, a.name, a.sku, a.category,
    q.location_id, coalesce(loc.warehouse, '(geen locatie)'), loc.shelf, loc.box, coalesce(loc.kind, 'shelf'), loc.technician_id,
    q.quantity,
    coalesce(c.unit_cost_cents, a.purchase_price_cents),
    case when coalesce(loc.kind, 'shelf') = 'quarantine' then 0::bigint
         else greatest(q.quantity, 0) * coalesce(c.unit_cost_cents, a.purchase_price_cents, 0) end,
    c.unit_cost_cents is null
  from qty q
  join public.kfc_articles a on a.code = q.article_code
  left join public.kfc_locations loc on loc.id = q.location_id
  left join cost c on c.article_code = q.article_code
  where (p_warehouse = '' or coalesce(loc.warehouse, '(geen locatie)') = p_warehouse)
    and (p_category = '' or a.category = p_category);
$$;

-- ---------------------------------------------------------------------------
-- Stock ledger: every move in the period with the article's running balance
-- (all locations) after the move, plus the opening balance before the period.
-- One page at a time; p_page_size 0 = everything (for export, capped at 50 000).
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_ledger(
  p_from date, p_to date, p_article text default '', p_reason text default '', p_warehouse text default '',
  p_query text default '', p_page integer default 1, p_page_size integer default 100
) returns jsonb language sql stable set search_path = '' as $$
  with bounds as (
    select p_from::timestamp at time zone 'Europe/Amsterdam' as starts,
           (p_to + 1)::timestamp at time zone 'Europe/Amsterdam' as ends
  ), arts as (
    select a.code, a.name, a.sku, a.category, a.purchase_price_cents from public.kfc_articles a
    where (p_article = '' or a.code = p_article)
      and (p_query = '' or strpos(lower(a.code), lower(p_query)) > 0 or strpos(lower(a.name), lower(p_query)) > 0
           or strpos(lower(a.sku), lower(p_query)) > 0)
  ), running as (
    select m.id, m.created_at, m.article_code, m.location_id, m.delta, m.quantity_after, m.reason,
      m.unit_cost_cents, m.note, m.order_line_id, m.sales_invoice_id, m.purchase_order_line_id, m.count_batch_id, m.created_by,
      sum(m.delta) over (partition by m.article_code order by m.created_at, m.id) as balance
    from public.kfc_stock_moves m
    join arts on arts.code = m.article_code
    cross join bounds
    where m.created_at < bounds.ends
  ), period as (
    select r.*, arts.name, arts.sku, arts.category,
      loc.warehouse, loc.shelf, loc.box,
      coalesce(r.unit_cost_cents, arts.purchase_price_cents) * r.delta as value_cents,
      po.supplier, so.number as order_number, si.invoice_number
    from running r
    join arts on arts.code = r.article_code
    cross join bounds
    left join public.kfc_locations loc on loc.id = r.location_id
    left join public.kfc_purchase_order_lines pl on pl.id = r.purchase_order_line_id
    left join public.kfc_purchase_orders po on po.id = pl.po_id
    left join public.kfc_shop_order_lines sl on sl.id = r.order_line_id
    left join public.kfc_shop_orders so on so.id = sl.order_id
    left join public.sales_invoices si on si.id = r.sales_invoice_id
    where r.created_at >= bounds.starts
      and (p_reason = '' or r.reason = p_reason)
      and (p_warehouse = '' or loc.warehouse = p_warehouse)
  ), opening as (
    select coalesce(sum(m.delta), 0) as qty
    from public.kfc_stock_moves m join arts on arts.code = m.article_code cross join bounds
    where m.created_at < bounds.starts
  ), totals as (
    select count(*) as n,
      coalesce(sum(delta) filter (where delta > 0), 0) as incoming,
      coalesce(-sum(delta) filter (where delta < 0), 0) as outgoing
    from period
  )
  select jsonb_build_object(
    'opening', (select qty from opening),
    'count', totals.n, 'incoming', totals.incoming, 'outgoing', totals.outgoing,
    'rows', coalesce((
      select jsonb_agg(to_jsonb(v) order by v.created_at desc, v.id desc) from (
        select * from period order by created_at desc, id desc
        limit case when p_page_size <= 0 then 50000 else p_page_size end
        offset case when p_page_size <= 0 then 0 else (greatest(p_page, 1)::bigint - 1) * p_page_size end
      ) v), '[]'::jsonb)
  ) from totals;
$$;

-- ---------------------------------------------------------------------------
-- Stock ageing (FIFO): the current physical stock is taken to be the most
-- recent inbound moves (receipt, assembly, return, positive count/correction;
-- transfers are internal and skipped). Stock older than every recorded inbound
-- has an unknown age and is counted in the oldest bucket.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_stock_ageing(p_category text default '')
returns table (
  code text, name text, sku text, category text, physical integer, unit_cost_cents integer, value_cents bigint,
  q_0_30 bigint, q_31_60 bigint, q_61_90 bigint, q_91_180 bigint, q_181_365 bigint, q_365p bigint,
  oldest_days integer, avg_days numeric, last_received_at timestamptz, last_sold_at timestamptz
) language sql stable set search_path = '' as $$
  with stock as (
    select o.code, o.name, o.sku, o.category, o.physical, o.purchase_price_cents, o.last_received_at, o.last_sold_at
    from public.kfc_article_overview o
    where o.physical > 0 and (p_category = '' or o.category = p_category)
  ), inbound as (
    select m.article_code, m.created_at, m.delta,
      sum(m.delta) over (partition by m.article_code order by m.created_at desc, m.id desc) as cum
    from public.kfc_stock_moves m
    join stock s on s.code = m.article_code
    where m.delta > 0 and m.reason <> 'transfer'
  ), alloc as (
    select i.article_code,
      greatest(0, least(i.delta, s.physical - (i.cum - i.delta)))::bigint as qty,
      (now() at time zone 'Europe/Amsterdam')::date - (i.created_at at time zone 'Europe/Amsterdam')::date as age
    from inbound i join stock s on s.code = i.article_code
  ), known as (
    select article_code,
      sum(qty) as qty,
      sum(qty) filter (where age <= 30) as a30, sum(qty) filter (where age between 31 and 60) as a60,
      sum(qty) filter (where age between 61 and 90) as a90, sum(qty) filter (where age between 91 and 180) as a180,
      sum(qty) filter (where age between 181 and 365) as a365, sum(qty) filter (where age > 365) as a365p,
      max(age) filter (where qty > 0) as oldest,
      sum(qty * age) as weighted
    from alloc group by article_code
  )
  select s.code, s.name, s.sku, s.category, s.physical::integer, s.purchase_price_cents,
    s.physical::bigint * coalesce(s.purchase_price_cents, 0),
    coalesce(k.a30, 0)::bigint, coalesce(k.a60, 0)::bigint, coalesce(k.a90, 0)::bigint,
    coalesce(k.a180, 0)::bigint, coalesce(k.a365, 0)::bigint,
    (coalesce(k.a365p, 0) + greatest(s.physical - coalesce(k.qty, 0), 0))::bigint,
    case when s.physical > coalesce(k.qty, 0) then null else k.oldest end::integer,
    case when coalesce(k.qty, 0) = 0 then null else round(k.weighted::numeric / k.qty, 0) end,
    s.last_received_at, s.last_sold_at
  from stock s left join known k on k.article_code = s.code;
$$;

-- ---------------------------------------------------------------------------
-- Header totals of the article list in one pass over the overview.
-- ---------------------------------------------------------------------------
create or replace function public.kfc_article_totals()
returns jsonb language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'articles', count(*),
    'in_stock', count(*) filter (where physical > 0),
    'low',      count(*) filter (where stock_state = 'laag'),
    'zero',     count(*) filter (where stock_state = 'nul'),
    'negative', count(*) filter (where stock_state = 'negatief'),
    'incoming', count(*) filter (where incoming > 0),
    'value',    coalesce(sum(stock_value_cents), 0),
    'unpriced', count(*) filter (where unpriced and physical > 0)
  ) from public.kfc_article_overview;
$$;

-- Security ---------------------------------------------------------------------
revoke all on public.kfc_sales_lines from public, anon, authenticated;
revoke all on public.kfc_article_overview from public, anon, authenticated;
grant select on public.kfc_sales_lines to service_role;
grant select on public.kfc_article_overview to service_role;

revoke all on function public.kfc_sales_report(date, date, text, text, text, text) from public, anon, authenticated;
revoke all on function public.kfc_article_movement(date, date, text) from public, anon, authenticated;
revoke all on function public.kfc_stock_valuation(date, text, text) from public, anon, authenticated;
revoke all on function public.kfc_stock_ledger(date, date, text, text, text, text, integer, integer) from public, anon, authenticated;
revoke all on function public.kfc_stock_ageing(text) from public, anon, authenticated;
revoke all on function public.kfc_article_totals() from public, anon, authenticated;
grant execute on function public.kfc_sales_report(date, date, text, text, text, text) to service_role;
grant execute on function public.kfc_article_movement(date, date, text) to service_role;
